INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-34-UND-01', 'English Literacy', 'understanding', '3-4', 'standard', 'Read the sentence: "Leo the puppy buried his favorite rubber bone under the old oak tree so his sister Maya would not chew it." Why did Leo bury the bone?', '[{"text":"He wanted to keep it safe from Maya.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"He forgot where the tree was.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He disliked playing with rubber toys.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Maya instructed him to bury it.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Identifying character motivation and causal relationships in narrative text.', 'Look for the reason right after the word "so" in the sentence.', 1.1, -1.7, 0.25, true, 0, 'Cambridge Primary English Stage 3 / Singapore Primary 3'),
('ENG-34-UND-02', 'English Literacy', 'understanding', '3-4', 'standard', 'Read: "Although it was pouring rain, Sarah put on her yellow raincoat and walked happily toward the giant puddle." How did Sarah feel about the rainy weather?', '[{"text":"She felt gloomy and wanted to stay indoors.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"She was frightened of getting her clothes wet.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"She was joyful and excited to play in the rain.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"She was angry that her trip was cancelled.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring character feelings and attitudes from actions and descriptive words.', 'Notice the word "happily" and how Sarah walked toward the puddle.', 1.15, -1.5, 0.25, true, 0, 'Singapore MOE Primary 3 English'),
('ENG-34-UND-03', 'English Literacy', 'understanding', '3-4', 'standard', '"Every winter, the bear retreats into a cozy cave and enters a deep sleep until spring flowers bloom." What is the main idea of this sentence?', '[{"text":"Spring flowers grow inside dark caves.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bears hibernate in caves during the cold winter months.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Bears only wake up when other animals call them.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Winter is the best season for bears to hunt food.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Determining the main idea of a short informational sentence.', 'Consider what the whole sentence is describing about the bear’s winter habits.', 1.2, -1.4, 0.25, true, 0, 'US Common Core Grade 3 Reading Informational Text'),
('ENG-34-UND-04', 'English Literacy', 'understanding', '3-4', 'standard', '"Toby dropped his ice cream cone on the sidewalk. His lower lip quivered, and tears welled up in his eyes." How does Toby feel?', '[{"text":"Disappointed and sad about losing his treat.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Surprised by how warm the sidewalk was.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Proud of sharing his ice cream with ants.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bored and ready to go home.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring emotional states from physical character cues.', 'What do a quivering lip and tears usually show?', 1.1, -1.6, 0.25, true, 0, 'PIRLS Grade 4 Literary Experience'),
('ENG-34-UND-05', 'English Literacy', 'understanding', '3-4', 'standard', '"The little red hen asked her barnyard friends to help plant wheat seeds, but the duck and cat were too busy napping under the porch." What does this tell us about the duck and cat?', '[{"text":"They were skilled wheat farmers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were unwilling to help with farm chores.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"They were afraid of small seeds.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They wanted to plant corn instead.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing character traits and behaviors in fables.', 'Notice that they chose to nap instead of helping.', 1.2, -1.3, 0.25, true, 0, 'Cambridge Primary Stage 4'),
('ENG-34-UND-06', 'English Literacy', 'understanding', '3-4', 'advanced', '"The grandfather clock in the hallway stood like a tall wooden soldier guarding the quiet house." What comparison is being made here?', '[{"text":"The steady, upright clock is compared to a standing soldier.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A real soldier is hiding inside the wooden clock.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The house is actively being attacked by an army.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The grandfather prefers soldiers over clocks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting simple similes and figurative imagery.', 'Look for the word "like" which connects the clock and the soldier.', 1.3, -0.9, 0.25, true, 0, 'Singapore Primary 4 English Literature'),
('ENG-34-UND-07', 'English Literacy', 'understanding', '3-4', 'advanced', '"The desert chameleon blended so perfectly into the sand that the hawk flew right past without noticing." Why was the hawk unable to spot the chameleon?', '[{"text":"The chameleon ran into an underground tunnel.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The hawk was flying backward.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The sand was too bright for any bird to see.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The chameleon used camouflage to match the color of the ground.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Understanding cause and effect in descriptive informational passages.', 'Focus on how blending into the sand protects the chameleon.', 1.25, -0.8, 0.25, true, 0, 'US NGSS / Common Core Grade 4'),
('ENG-34-UND-08', 'English Literacy', 'understanding', '3-4', 'advanced', '"After three hours of hiking up the rocky trail, Anya finally saw the mountain peak gleaming in the afternoon sun. She took a deep breath and smiled." What is the theme of this moment?', '[{"text":"Effort and perseverance leading to a rewarding achievement.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The dangers of hiking without proper hiking shoes.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Why mountains are colder than valley plains.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"How sunlight can damage your vision.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deriving overarching theme from narrative resolution.', 'Consider the effort Anya put in and how she felt when she reached her goal.', 1.35, -0.7, 0.25, true, 0, 'PIRLS Grade 4 Core Reading'),
('ENG-34-UND-09', 'English Literacy', 'understanding', '3-4', 'olympiad', '"The sudden silence in the aviary was louder than any squawk; every bird froze as a shadow glided overhead." Why does the author call the silence "louder than any squawk"?', '[{"text":"To prove that silence creates physical sound waves.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Because the birds were screaming in high-pitched frequencies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"To emphasize how dramatic, alarming, and noticeable the quiet was.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Because the roof of the aviary collapsed.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing literary paradox and authorial emphasis in Grade 3-4 text.', 'When everything goes dead silent instantly, what does that sudden change feel like?', 1.5, -0.4, 0.25, true, 0, 'Singapore Primary English Olympiad / SASMO Foundation'),
('ENG-34-UND-10', 'English Literacy', 'understanding', '3-4', 'olympiad', '"Grandma''s kitchen was always a busy workshop of simmering pots, flying flour, and stories passed down through generations." What does the word "workshop" suggest about the kitchen?', '[{"text":"It was an untidy and hazardous factory environment.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was used for repairing broken wooden chairs and tools.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was an active, creative place where food and traditions were lovingly crafted.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"It was strictly reserved for professional cooks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting metaphorical language and connotative meaning.', 'Think about what happens in a workshop—things are made with care and effort.', 1.45, -0.3, 0.25, true, 0, 'Cambridge Primary Checkpoint English'),
('ENG-34-LOC-01', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Notice: "School Library Schedule: Monday–Thursday: 8:00 AM – 3:30 PM. Friday: Closed for shelf organization." On which day is the library closed for shelf organization?', '[{"text":"Friday","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Monday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Wednesday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Thursday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Direct retrieval of specific facts from simple schedules.', 'Scan the notice for the word "Closed" and look at the day listed right before it.', 1.2, -1.8, 0.25, true, 0, 'PIRLS Grade 4 Information Retrieval'),
('ENG-34-LOC-02', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Recipe Card: "Honey Berry Parfait: 1 cup Greek yogurt, 0.5 cup rolled oats, 2 tablespoons wild honey, 1 sliced ripe kiwi. Chill in the refrigerator for 15 minutes before serving." How much wild honey is needed?', '[{"text":"15 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1 cup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.5 cup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2 tablespoons","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating precise measurements and ingredients in functional procedural text.', 'Locate the ingredient "wild honey" and read the amount specified.', 1.25, -1.7, 0.25, true, 0, 'Singapore Primary 3 English Functional Reading'),
('ENG-34-LOC-03', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Museum Flyer: "Dinosaur Discovery Hall: Level 1. Space & Rockets Gallery: Level 3. Butterfly Pavilion: Rooftop Garden (Level 4)." On which level can visitors find the Space & Rockets Gallery?', '[{"text":"Level 4","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 1","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 2","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 3","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning informational brochures for specific location details.', 'Search directly for the words "Space & Rockets Gallery".', 1.3, -1.6, 0.25, true, 0, 'Cambridge Primary Stage 3'),
('ENG-34-LOC-04', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Weather Report: "Sunrise will occur at 6:15 AM. Highest daytime temperature will reach 28°C with moderate breezes from the northeast." What is the expected peak temperature?', '[{"text":"15°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"6:15 AM","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"28°C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"35°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving numerical data from short informational reports.', 'Find the section mentioning temperature.', 1.2, -1.5, 0.25, true, 0, 'US Common Core Grade 3 Reading'),
('ENG-34-LOC-05', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Pet Care Guide: "Hamsters must be given fresh water every morning. Clean their wood shaving bedding once each week, and provide fresh carrot slices twice a week." How often should hamster bedding be cleaned?', '[{"text":"Every morning","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Once each week","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Twice a week","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Once a month","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Distinguishing between multiple time frequencies in a procedural passage.', 'Pay close attention to what corresponds specifically to "bedding".', 1.35, -1.4, 0.25, true, 0, 'PIRLS Grade 4 Information Tasks'),
('ENG-34-LOC-06', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'School Bus Rules: "Students must remain seated until the bus halts completely. Backpacks must be placed beneath your seat or on your lap. Eating peanuts is strictly forbidden." Where should backpacks be stored?', '[{"text":"In the overhead luggage rack","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"In the aisle between seats","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Beneath the seat or on the student''s lap","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Next to the bus driver","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting specific rules and storage instructions from safety guidelines.', 'Look for the sentence starting with "Backpacks".', 1.3, -1, 0.25, true, 0, 'Singapore Primary 4 English'),
('ENG-34-LOC-07', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'Camp Itinerary: "08:00 Birdwatching along Maple Creek; 10:30 Kayak paddling practice; 12:30 Outdoor campfire lunch; 14:00 Orienteering navigation game." What activity takes place right before lunch?', '[{"text":"Orienteering navigation game","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Birdwatching along Maple Creek","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Kayak paddling practice","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Campfire cleanup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Interpreting chronological order in daily itineraries.', 'Look at the activity scheduled at 10:30, right before the 12:30 lunch.', 1.4, -0.9, 0.25, true, 0, 'Cambridge Primary Stage 4'),
('ENG-34-LOC-08', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'Plant Factfile: "The Venus Flytrap is native only to the coastal bogs of North and South Carolina. Its leaves close in roughly 0.1 seconds when trigger hairs are brushed." In how much time do the leaves snap shut?', '[{"text":"10 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Roughly 0.1 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"1 minute","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"30 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exact numerical scientific facts in descriptive prose.', 'Scan for the number followed by the time unit "seconds".', 1.35, -0.8, 0.25, true, 0, 'US Common Core Grade 4'),
('ENG-34-LOC-09', 'English Literacy', 'locatingInformation', '3-4', 'olympiad', 'Historical Log: "Captain Miller documented that the schooner arrived at Port Jackson on October 14, carrying 120 barrels of olive oil, 45 crates of dried figs, and three boxes of brass navigation sextants." How many crates of dried figs were recorded?', '[{"text":"120 barrels","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"45 crates","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"3 boxes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"14 crates","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning dense inventory lists for precise item-quantity pairings.', 'Pair each number with its exact cargo description.', 1.5, -0.5, 0.25, true, 0, 'Singapore Primary English Olympiad'),
('ENG-34-LOC-10', 'English Literacy', 'locatingInformation', '3-4', 'olympiad', 'Wildlife Bulletin: "The Arctic tern migrates from Greenland to Antarctica and back each year, covering nearly 71,000 kilometers annually—the longest recorded journey of any animal on Earth." Between which two geographic regions does this bird travel?', '[{"text":"Norway and South Africa","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Canada and Australia","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Alaska and South America","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Greenland and Antarctica","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating origin and destination entities in geographic informational text.', 'Look for the "from ... to ..." phrase in the passage.', 1.45, -0.4, 0.25, true, 0, 'ICSE Grade 4 English Literature & Language')
ON CONFLICT (scenario_code) DO UPDATE SET
  subject = EXCLUDED.subject,
  competency = EXCLUDED.competency,
  developmental_band = EXCLUDED.developmental_band,
  difficulty = EXCLUDED.difficulty,
  prompt = EXCLUDED.prompt,
  options = EXCLUDED.options,
  learning_objective = EXCLUDED.learning_objective,
  hint = EXCLUDED.hint,
  irt_a = EXCLUDED.irt_a,
  irt_b = EXCLUDED.irt_b,
  irt_c = EXCLUDED.irt_c,
  is_active = EXCLUDED.is_active,
  international_benchmark = EXCLUDED.international_benchmark;

INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-34-SYN-01', 'English Literacy', 'synthesis', '3-4', 'standard', 'Fact 1: "Green plants require sunlight to create food through photosynthesis." Fact 2: "Rohan placed his bean sprout inside a dark wardrobe for two weeks, watering it every day." What will happen to Rohan''s plant?', '[{"text":"The plant will produce dark purple flowers inside the wardrobe.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The plant will grow twice as fast because it had plenty of water.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The bean sprout will turn pale and fail to grow healthy leaves because it lacked sunlight.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The plant will transform into a mushroom.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing two pieces of factual evidence to predict a scientific outcome.', 'Combine the requirement in Fact 1 with what was missing in Fact 2.', 1.25, -1.3, 0.25, true, 0, 'Singapore Primary 3 Science & English Integration'),
('ENG-34-SYN-02', 'English Literacy', 'synthesis', '3-4', 'standard', 'Notice A: "The swimming pool closes whenever lightning flashes within 5 miles." Notice B: "At 2:00 PM, thunder rumbled and lightning struck a radio tower 2 miles from the pool." What action must the lifeguard take?', '[{"text":"Allow swimmers to stay in the water if they wear goggles.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Order all swimmers out of the pool and close the facility immediately.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Turn on the pool heaters to protect the swimmers.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Wait for two hours before making any announcements.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Integrating a safety rule with a situational occurrence.', 'Is 2 miles within the 5-mile safety radius mentioned in Notice A?', 1.3, -1.2, 0.25, true, 0, 'Cambridge Primary Stage 3 English'),
('ENG-34-SYN-03', 'English Literacy', 'synthesis', '3-4', 'standard', 'Story 1: "Liam loved playing soccer, but he practiced alone in his backyard every evening." Story 2: "When Liam joined the town youth team, he struggled to pass the ball to open teammates." What skill does Liam need to develop?', '[{"text":"Teamwork and communicating with other players during a game.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Kicking the ball harder toward the goalposts.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Buying more expensive soccer boots.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Practicing soccer only once a month.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing character backstory with a social challenge.', 'Consider the difference between practicing alone and playing on a team.', 1.2, -1.1, 0.25, true, 0, 'US Common Core Grade 3 Reading'),
('ENG-34-SYN-04', 'English Literacy', 'synthesis', '3-4', 'standard', 'Text A: "Bees carry pollen from flower to flower, helping apple trees produce fruit." Text B: "A sudden cold freeze killed the local bee colony in early spring." What will most likely happen to the orchard''s apple harvest in autumn?', '[{"text":"The orchard will start growing oranges instead.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The apple trees will produce giant red apples immediately.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The orchard will produce significantly fewer apples because pollination was disrupted.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The cold freeze will make the apples sweeter than usual.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Deducing cause-and-effect across biological ecological texts.', 'If bees help trees make fruit, what happens when there are no bees?', 1.35, -1, 0.25, true, 0, 'PIRLS Grade 4 Synthesis'),
('ENG-34-SYN-05', 'English Literacy', 'synthesis', '3-4', 'advanced', 'Book Log: "Maya read 15 pages on Monday and 25 pages on Tuesday. Her brother Noah read 10 pages each day from Monday through Wednesday." Who read more total pages by Wednesday evening?', '[{"text":"Maya read 40 pages while Noah read 30 pages, so Maya read more.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Noah read more because he read on three separate days.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Both read the exact same number of pages.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Noah read 50 pages while Maya read 35 pages.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Combining multi-sentence quantitative statements into a comparative conclusion.', 'Add Maya''s pages (15 + 25) and compare to Noah''s pages (10 + 10 + 10).', 1.4, -0.7, 0.25, true, 0, 'Singapore Primary 4 Mathematics & English'),
('ENG-34-SYN-06', 'English Literacy', 'synthesis', '3-4', 'advanced', 'Source 1: "Earthworms tunnel through soil, creating channels that allow oxygen and rainwater to reach plant roots." Source 2: "Gardeners often add compost and encourage worms in their vegetable patches." Why do gardeners welcome earthworms?', '[{"text":"Because worms make the soil completely dry.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Because worms frighten away birds and rabbits.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Because worms eat vegetable weeds before they sprout.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Because earthworms naturally aerate the soil and support healthy root growth.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing ecological function with human agricultural practice.', 'Connect the channels earthworms dig with what plant roots need to thrive.', 1.35, -0.6, 0.25, true, 0, 'Cambridge Primary Checkpoint Stage 4'),
('ENG-34-SYN-07', 'English Literacy', 'synthesis', '3-4', 'advanced', 'Passage 1: "The town bridge was built of timber planks in 1850." Passage 2: "Modern heavy cargo trucks weigh five times more than horse-drawn wagons from 1850." Passage 3: "The town council recently banned cargo trucks from crossing the bridge." Why did the council enact this ban?', '[{"text":"The trucks were too loud for fish swimming beneath the bridge.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The council prefers horse-drawn wagons for daily transport.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The historic wooden bridge was not designed to bear the heavy weight of modern trucks.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Timber planks become stronger when heavy trucks drive over them.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Integrating historical material constraints with modern civic regulations.', 'Connect the weight of modern trucks with the age and material of the bridge.', 1.45, -0.5, 0.25, true, 0, 'US Common Core Grade 4 Informational Text'),
('ENG-34-SYN-08', 'English Literacy', 'synthesis', '3-4', 'olympiad', 'Report A: "Emperor penguins huddle tightly in circles containing hundreds of birds during blizzards." Report B: "Thermal sensors show that the center of an emperor penguin huddle reaches 37°C while the outer air is -40°C." Report C: "Penguins continuously take turns rotating from the freezing outer rim to the warm core." What is the adaptive purpose of this rotation?', '[{"text":"It confuses predatory leopard seals swimming underneath the ice.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It allows the strongest penguins to stay permanently at the center.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It ensures that all members of the colony share equitable access to warmth and survive the storm.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"It helps the penguins practice marching in military formations.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing biological observation with thermal data and behavioral adaptation.', 'What would happen to the penguins stuck on the outside if they never swapped places?', 1.55, -0.2, 0.25, true, 0, 'Singapore Primary English Olympiad / SASMO'),
('ENG-34-SYN-09', 'English Literacy', 'synthesis', '3-4', 'olympiad', 'Text 1: "Solar cookers use curved shiny mirrors to concentrate sunlight onto a dark cooking pot." Text 2: "In arid regions with scarce firewood, solar cookers prevent families from having to cut down scarce desert shrubs." What environmental benefit results from using solar cookers in arid areas?', '[{"text":"Conserving fragile desert vegetation and curbing local deforestation.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Increasing the amount of smoke and soot in household kitchens.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Making desert shrubs grow twice as tall.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Eliminating the need for drinking water in desert villages.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing technological mechanisms with ecological conservation outcomes.', 'Think about what happens to the desert trees when people do not need firewood.', 1.5, -0.1, 0.25, true, 0, 'Cambridge Primary Stage 4 Advanced'),
('ENG-34-SYN-10', 'English Literacy', 'synthesis', '3-4', 'olympiad', 'Tale 1: "The swift hare boasted that no animal could ever match his speed." Tale 2: "The slow tortoise committed to walking without pausing a single second." Tale 3: "Overconfident in his lead, the hare fell asleep under a tree while the tortoise steadily crossed the finish line." What core life lesson emerges from combining these tales?', '[{"text":"Consistent diligence and modesty can triumph over arrogant, unapplied natural talent.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Sleeping during the daytime is always healthy for athletes.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Fast runners should never participate in friendly contests.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Tortoises are biologically swifter than resting hares.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing narrative arcs into an overarching moral axiom.', 'Compare the hare''s attitude with the tortoise''s steady effort.', 1.6, 0, 0.25, true, 0, 'ICSE Grade 4 English Literature'),
('ENG-34-EVL-01', 'English Literacy', 'evaluatingReflecting', '3-4', 'standard', '"Drink ZapJuice! It gives you instant superhero wings and laser speed!" What is the main intention of this advertisement?', '[{"text":"To warn consumers about flying safety hazards.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"To persuade children to buy the drink using playful exaggeration.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"To scientifically explain how bird wings grow.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"To give accurate nutritional data about vitamins.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Identifying the persuasive purpose and hyperbole in commercial advertisements.', 'Can a fruit juice really grow wings on your back?', 1.2, -1.4, 0.25, true, 0, 'PIRLS Grade 4 Critical Reading'),
('ENG-34-EVL-02', 'English Literacy', 'evaluatingReflecting', '3-4', 'standard', 'Poster: "Help Keep Our Playground Clean! Toss wrappers into the recycling bins." What tone does this poster use?', '[{"text":"Humorous and sarcastic.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Furious and threatening.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Encouraging and civic-minded.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Sorrowful and tearful.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Recognizing community tone and civic voice in public notices.', 'Notice the friendly words "Help Keep Our Playground Clean!".', 1.15, -1.3, 0.25, true, 0, 'Singapore Primary 3 English'),
('ENG-34-EVL-03', 'English Literacy', 'evaluatingReflecting', '3-4', 'standard', '"The stormy wind howled like an angry wolf rattling the window shutters." Why did the author describe the wind as an "angry wolf"?', '[{"text":"To make the storm feel fierce, noisy, and frightening to the reader.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"To inform the reader that a real wolf was outside the house.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"To explain that wolves enjoy blowing air on shutters.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"To prove that window shutters are built of wolf fur.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating author''s craft and the impact of figurative language on mood.', 'What feeling does an "angry wolf" howling create inside a cozy room?', 1.25, -1.1, 0.25, true, 0, 'Cambridge Primary Stage 3'),
('ENG-34-EVL-04', 'English Literacy', 'evaluatingReflecting', '3-4', 'standard', 'A student writes: "Cats are 100% better than dogs because dogs are way too energetic and cats love to nap peacefully." Is this statement a fact or an opinion?', '[{"text":"It is a law passed by the city council.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It is a verified scientific fact proved by veterinarians.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It is a mathematical calculation about animal speed.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It is an opinion because personal preferences about pets differ from person to person.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Distinguishing between personal opinion and empirical fact.', 'Can everyone agree on whether energetic dogs or quiet cats are "better"?', 1.3, -1, 0.25, true, 0, 'US Common Core Grade 3 Reading'),
('ENG-34-EVL-05', 'English Literacy', 'evaluatingReflecting', '3-4', 'advanced', '"Don''t be the only kid on your street without the UltraGlide Scooter! Everyone is riding one!" Which advertising technique is being used here?', '[{"text":"Detailed statistical breakdown of wheel bearings.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Expert scientific testimony from engineers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Bandwagon appeal: making the reader feel left out if they do not join the group.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Historical evidence from the 19th century.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing persuasive peer-pressure and bandwagon rhetoric.', 'Notice phrases like "Don''t be the only kid" and "Everyone is riding one".', 1.35, -0.7, 0.25, true, 0, 'Singapore Primary 4 English'),
('ENG-34-EVL-06', 'English Literacy', 'evaluatingReflecting', '3-4', 'advanced', 'Two reviews of a children''s book: Reviewer 1 writes: "The colorful illustrations are dazzling and the story is hilarious!" Reviewer 2 writes: "The book is printed on glossy paper and contains 32 pages." Which review expresses an evaluative judgment?', '[{"text":"Reviewer 1, because words like \"dazzling\" and \"hilarious\" express subjective appreciation.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Reviewer 2, because counting pages requires deep critical thinking.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Both reviews are strictly objective scientific measurements.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Neither review provides any information about the book.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating subjective appraisal versus neutral descriptive reporting.', 'Look for descriptive words that share personal taste rather than physical specs.', 1.4, -0.6, 0.25, true, 0, 'Cambridge Primary Stage 4 Checkpoint'),
('ENG-34-EVL-07', 'English Literacy', 'evaluatingReflecting', '3-4', 'advanced', 'In a story about an injured bird, the author finishes with: "As the sparrow took flight into the blue sky, Maya felt her own worries lift away with its wings." How does the author connect the bird''s flight with Maya''s feelings?', '[{"text":"The author is explaining how bird feathers deflect wind.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Maya physically flew through the air alongside the sparrow.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The bird taught Maya how to avoid doing homework.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The physical release of the healed bird symbolizes Maya''s emotional relief and freedom.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Reflecting on symbolic parallels between external actions and internal emotional states.', 'What does watching something fly away feel like when you have heavy worries?', 1.4, -0.5, 0.25, true, 0, 'PIRLS Grade 4 Reflection'),
('ENG-34-EVL-08', 'English Literacy', 'evaluatingReflecting', '3-4', 'olympiad', '"The mayor proclaimed that building a four-lane highway through the municipal wildflower park would bring unprecedented prosperity, conveniently neglecting to mention that three hundred century-old oaks would be felled." What stance does the author hold toward the mayor''s proclamation?', '[{"text":"Critical and skeptical, exposing the hidden environmental cost the mayor ignored.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Enthusiastic and celebratory regarding highway construction.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Completely indifferent to both the park and the highway.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Praising the mayor''s transparent honesty.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Detecting authorial irony, bias, and critical stance in editorial reporting.', 'Notice the phrase "conveniently neglecting to mention".', 1.55, -0.2, 0.25, true, 0, 'Singapore Primary English Olympiad'),
('ENG-34-EVL-09', 'English Literacy', 'evaluatingReflecting', '3-4', 'olympiad', 'An author describes two brothers: "Julian polished his silver medals until they mirrored his vanity; Arthur slipped his quietly into a desk drawer and headed outside to coach the younger children." How does the author subtly guide the reader''s moral judgment?', '[{"text":"By proving that Julian is an ineffective athlete.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By demonstrating that silver is a superior metal to gold.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By contrasting Julian''s self-absorbed pride with Arthur''s humble generosity.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"By arguing that children should not be coached outdoors.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing how character juxtaposition shapes reader empathy and ethical judgment.', 'Look at what each brother does with his medals.', 1.5, -0.1, 0.25, true, 0, 'Cambridge Primary Stage 4 Advanced'),
('ENG-34-EVL-10', 'English Literacy', 'evaluatingReflecting', '3-4', 'olympiad', '"To label the ancient oak a simple tree is to call the ocean a puddle; it was an entire bustling city for countless squirrels, owls, and beetles." What rhetorical device is the author using to emphasize the tree''s ecological importance?', '[{"text":"Analogy and contrast to highlight how vast and vital the tree''s miniature ecosystem is.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Literal description proving that squirrels hold municipal elections.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Statistical sampling of ocean water salinity.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A chronological historical timeline of timber logging.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating figurative analogies and scale shifts in environmental prose.', 'Why does the author compare calling the tree "just a tree" to calling the ocean "a puddle"?', 1.6, 0.1, 0.25, true, 0, 'ICSE Grade 4 English Language')
ON CONFLICT (scenario_code) DO UPDATE SET
