  international_benchmark = EXCLUDED.international_benchmark;

INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-56-UND-01', 'English Literacy', 'understanding', '5-6', 'standard', '"The fennec fox remains sequestered subterraneanly throughout the blistering daylight hours, emerging only when twilight cools the Sahara dunes." What behavioral adaptation is described in this passage?', '[{"text":"Hunting diurnal desert rodents that only sleep when darkness falls.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Nocturnal behavior engineered to conserve internal moisture and avoid intense daytime heat.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Impaired eyesight that functions exclusively in dim twilight illumination.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Seasonal migration toward coastal salt marshes during peak summer.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting ecological adaptations and descriptive vocabulary in informational prose.', 'Consider why an animal would stay underground during daylight and come out at twilight.', 1.15, -0.7, 0.25, true, 0, 'Singapore Primary 5 English / MOE PSLE Preparation'),
('ENG-56-UND-02', 'English Literacy', 'understanding', '5-6', 'standard', '"The apprentice blacksmith watched the glowing iron bar slowly fade from brilliant orange to a sullen charcoal gray, realizing his window to hammer the blade had closed." What does "window" mean in this sentence?', '[{"text":"A limited opportunity or timeframe to shape the metal while it remained sufficiently malleable.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A glass pane set in the forge wall to vent toxic coal smoke.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A carved aperture through which the master smith evaluated work.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A measurement of the physical length of the cooling anvil.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deducing contextual and figurative word meanings from narrative context.', 'Think about what closes when metal cools down and becomes too hard to strike.', 1.2, -0.6, 0.25, true, 0, 'Cambridge Primary Stage 5 Checkpoint'),
('ENG-56-UND-03', 'English Literacy', 'understanding', '5-6', 'standard', '"The old botanist spoke of the rainforest canopy not as a passive ceiling of leaves, but as a dynamic emerald battlefield where vines and saplings wrestled incessantly for every ray of sunlight." What central impression does this passage convey?', '[{"text":"The quiet serenity and complete harmony of an untouched tropical ecosystem.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Intense, ongoing competition among plant species for vital solar energy.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The damage caused by human lumber companies felling ancient trees.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The poisonous nature of creeping vines on the forest floor.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing metaphor and authorial conception of ecological dynamics.', 'Notice the words "battlefield", "wrestled", and "competition for sunlight".', 1.25, -0.5, 0.25, true, 0, 'US Common Core Grade 5 Informational Text'),
('ENG-56-UND-04', 'English Literacy', 'understanding', '5-6', 'standard', '"Elena stood at the crossroads. To the left lay the well-worn cobblestones of her village; to the right, an overgrown path vanished into the mist. She checked her compass, adjusted her rucksack, and stepped firmly to the right." What does Elena''s decision reveal about her character?', '[{"text":"Courage, self-reliance, and a deliberate willingness to embrace uncertain adventures.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Foolishness and an inability to read a standard magnetic compass.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A deep hatred for cobblestones and village life.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Regret over leaving behind her childhood friends.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring character archetypes and traits from symbolic choices.', 'She took the unknown overgrown path deliberately after checking her tools.', 1.3, -0.4, 0.25, true, 0, 'PIRLS Grade 5 Reading Literary Experience'),
('ENG-56-UND-05', 'English Literacy', 'understanding', '5-6', 'standard', '"In honeybee colonies, the waggle dance is not random twitching; it is a sophisticated spatial compass that encodes the precise angle relative to the sun and the distance to nectar sources." What is the main idea of this excerpt?', '[{"text":"The sun''s ultraviolet radiation damages the nervous system of worker bees.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bees dance purely to celebrate the arrival of springtime flowers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Honeybee waggle dances serve as an intricate symbolic system for communicating food locations.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Honeybees rely entirely on scent trails rather than visual communication.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Summarizing key scientific concepts and functional animal behavior.', 'Focus on what the waggle dance communicates: angle and distance to food.', 1.2, -0.5, 0.25, true, 0, 'CBSE / ICSE Class 5 English'),
('ENG-56-UND-06', 'English Literacy', 'understanding', '5-6', 'advanced', '"The museum conservator scrutinized the painting under ultraviolet light, discovering that beneath the tranquil landscape lay an agitated, unfinished self-portrait of the artist." What does this revelation imply about the artist''s process?', '[{"text":"The painting had been created by two rival artists fighting over one easel.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The artist reused canvas, deliberately concealing an earlier intense personal work under a calm exterior.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Ultraviolet rays chemically altered the colors of the original oil paint.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The artist forgot how to paint landscapes and switched to portraits.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring hidden artistic intentionality from physical forensic evidence.', 'Why would someone paint a peaceful scene right over an agitated self-portrait?', 1.35, -0.2, 0.25, true, 0, 'Singapore Primary 6 PSLE Foundation'),
('ENG-56-UND-07', 'English Literacy', 'understanding', '5-6', 'advanced', '"The silence that fell over the debate hall was not passive indifference; it was the tense, breathless pause of a jury weighing an irrevocable verdict." What does this comparison convey about the audience?', '[{"text":"They were exhausted and preparing to leave before the speaker finished.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were deeply engaged, captivated, and conscious of the heavy consequence of the argument.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"They were legally obligated to deliver a criminal court sentence.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were confused by the technical jargon used by the speaker.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing psychological tension and atmosphere created through metaphor.', 'Notice the contrast: not "passive indifference", but weighing an "irrevocable verdict".', 1.4, 0, 0.25, true, 0, 'Cambridge Secondary 1 Checkpoint Stage 6'),
('ENG-56-UND-08', 'English Literacy', 'understanding', '5-6', 'advanced', '"To Marcus, the laboratory was less a sterile room of test tubes and more an alchemist''s sanctuary, where common minerals were coaxed into shedding their mundane secrets." What does the author suggest about Marcus''s perspective on science?', '[{"text":"He views scientific research as an imaginative, almost magical pursuit of fundamental truth.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"He rejects modern chemistry in favor of fraudulent medieval superstitions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He finds laboratory safety protocols tedious and counterproductive.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He is primarily interested in transmuting lead into marketable gold jewelry.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing character worldview and intellectual temperament.', 'Notice terms like "sanctuary", "coaxed", and "shedding mundane secrets".', 1.35, 0.1, 0.25, true, 0, 'US Common Core Grade 6 Literature'),
('ENG-56-UND-09', 'English Literacy', 'understanding', '5-6', 'olympiad', '"The ancient aqueduct straddling the valley stood as a monument not merely to Roman hydraulic engineering, but to an unyielding refusal to let topography dictate civic ambition." What philosophical assertion underlies this statement?', '[{"text":"Roman builders prioritized ornamental stone architecture above practical water delivery.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Human determination and civil engineering can overcome severe natural geographical barriers to serve society.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Natural valleys are inherently hostile environments that must be demolished.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Aqueducts are ecologically destructive monuments that disrupt river currents.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting philosophical subtext in historical architecture commentary.', 'Notice: refusal to let "topography dictate civic ambition".', 1.5, 0.3, 0.25, true, 0, 'Singapore Primary English Olympiad / PSLE High Distinction'),
('ENG-56-UND-10', 'English Literacy', 'understanding', '5-6', 'olympiad', '"The critic noted that while the young pianist possessed flawless mechanical dexterity, her performance lacked the tender vulnerability of an artist who has known genuine grief." What shortcoming does the critic pinpoint?', '[{"text":"Poor choice of classical repertoire for an international audience.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Inaccurate timing and frequent missed notes in complex musical cadenzas.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Inadequate physical hand stamina during extended concerto movements.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Emotional depth and expressive authenticity, despite having perfect technical finger accuracy.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Differentiating between technical proficiency and expressive emotional artistry.', 'Contrast "flawless mechanical dexterity" with "lacked tender vulnerability".', 1.55, 0.4, 0.25, true, 0, 'Cambridge Checkpoint Stage 6 Olympiad Stream'),
('ENG-56-LOC-01', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Robotics Expo Guide: "Pavilion Alpha (Hall 1): Autonomous Drones; Pavilion Beta (Hall 3): Surgical Nanobots; Pavilion Gamma (Hall 4): Biomimetic Prosthetics. Keynote Address occurs in the Central Amphitheatre at 11:15 AM." Where can a visitor view surgical nanobots?', '[{"text":"Central Amphitheatre","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Alpha in Hall 1","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Gamma in Hall 4","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Pavilion Beta in Hall 3","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning technical conference guides for precise location identifiers.', 'Match "Surgical Nanobots" with its exact Pavilion and Hall designation.', 1.2, -0.8, 0.25, true, 0, 'PIRLS Grade 5 Factual Scanning'),
('ENG-56-LOC-02', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Space Probe Telemetry: "Probe Voyager-Prime crossed the heliopause at an orbital velocity of 17.2 km/s. Onboard hydrazine fuel reserves stand at 14.8 liters, sufficient to maintain antenna orientation toward Earth until November 2031." What is the remaining fuel volume?', '[{"text":"14.8 liters","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"17.2 km/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2031 liters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"50 liters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting specific scientific parameters and quantities from technical telemetry.', 'Scan for the phrase "fuel reserves stand at".', 1.25, -0.7, 0.25, true, 0, 'Singapore Primary 5 English'),
('ENG-56-LOC-03', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Archaeological Dig Bulletin: "Trench C revealed three distinct ceramic shards from the late Bronze Age, whereas Trench A contained exclusively iron spearheads dated to 650 BCE. Trench B has been suspended due to water seepage." Which trench yielded late Bronze Age ceramics?', '[{"text":"Trench C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Trench A","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Trench B","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Trench D","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Matching artifact types to spatial trench identifiers in field logs.', 'Find the sentence describing "ceramic shards from the late Bronze Age".', 1.3, -0.6, 0.25, true, 0, 'Cambridge Primary Stage 5'),
('ENG-56-LOC-04', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'Clean Energy Report: "While onshore wind turbines operate at an average capacity factor of 35%, offshore installations reach up to 52% owing to consistent maritime gale velocities. Solar photovoltaics in the same region average 21%." What is the capacity factor for offshore wind installations?', '[{"text":"21%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"35%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Up to 52%","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"100%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving precise comparative percentages across energy sectors.', 'Distinguish between "onshore", "offshore", and "solar".', 1.25, -0.5, 0.25, true, 0, 'US Common Core Grade 5 Informational Text'),
('ENG-56-LOC-05', 'English Literacy', 'locatingInformation', '5-6', 'standard', 'First Aid Protocol: "In case of thermal burns: cool the affected area immediately under clean, running lukewarm water for at least 20 minutes. Do not apply ice, butter, or adhesive bandages directly to blistered skin." For how long should lukewarm water be applied?', '[{"text":"At least 20 minutes","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"5 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2 hours","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Until ice is applied","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating mandatory procedural time thresholds in emergency protocols.', 'Scan for the time duration associated with "running lukewarm water".', 1.35, -0.4, 0.25, true, 0, 'Singapore Primary 6 English'),
('ENG-56-LOC-06', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Marine Biology Field Log: "Specimen 402, a giant Pacific octopus, demonstrated tactile problem-solving by opening a childproof medicine jar in 42 seconds. Specimen 405 completed the maze navigation task in 118 seconds after three preliminary orientation runs." How quickly did Specimen 402 open the jar?', '[{"text":"3 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"118 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"42 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"405 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Disentangling multiple numbered specimen IDs and distinct behavioral test times.', 'Look only at Specimen 402 and the task of opening the jar.', 1.4, -0.2, 0.25, true, 0, 'Cambridge Secondary 1 Stage 6'),
('ENG-56-LOC-07', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Aviation Handbook: "Maximum certified ceiling for Model Skyhawk-IV is 14,000 feet Mean Sea Level (MSL). Oxygen masks must be donned by all occupants if cabin pressure exceeds an altitude equivalent of 10,000 feet for more than 30 consecutive minutes." Under what condition must oxygen masks be donned?', '[{"text":"When cabin pressure exceeds a 10,000-foot equivalent for over 30 consecutive minutes.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Whenever the aircraft climbs above 5,000 feet.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Only upon landing at airports higher than 14,000 feet MSL.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Immediately upon starting the engines before takeoff.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving multi-conditional regulatory thresholds from technical guidelines.', 'Check both the altitude threshold and the time requirement.', 1.4, 0, 0.25, true, 0, 'US Common Core Grade 6 Informational'),
('ENG-56-LOC-08', 'English Literacy', 'locatingInformation', '5-6', 'advanced', 'Deep-Sea Research Dispatch: "At the Mariana Trench (Challenger Deep, 10,928 meters), hydrostatic pressure reaches approximately 1,086 bar—over 1,000 times atmospheric pressure at sea level. Despite this, xenophyophores, giant single-celled protozoans measuring up to 20 centimeters, thrive in the abyssal sediment." What is the maximum recorded size of xenophyophores mentioned?', '[{"text":"10,928 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Up to 20 centimeters","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"1,086 bar","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1 millimeter","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning high-density scientific abstracts for organism physical dimensions.', 'Focus on the organism "xenophyophores" and the dimension unit "centimeters".', 1.45, 0.1, 0.25, true, 0, 'Singapore Primary English Olympiad'),
('ENG-56-LOC-09', 'English Literacy', 'locatingInformation', '5-6', 'olympiad', 'Archival Treaty Summary: "Under Article VII of the 1894 Maritime Accord, coastal states retained exclusive salvage rights up to 12 nautical miles from the low-water baseline, provided formal diplomatic notice of recovery operations was submitted within 72 hours of vessel grounding." Within what timeframe must recovery notice be filed?', '[{"text":"Within 1894 hours of treaty ratification","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Within 12 days of salvage conclusion","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Within 72 hours of vessel grounding","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Immediately upon entering the 12-mile baseline","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating specific compliance windows within dense legal prose.', 'Find the time constraint tied to "diplomatic notice of recovery operations".', 1.5, 0.3, 0.25, true, 0, 'Cambridge Secondary Checkpoint High Distinction'),
('ENG-56-LOC-10', 'English Literacy', 'locatingInformation', '5-6', 'olympiad', 'Bioacoustics Field Study: "Recordings in the Svalbard archipelago confirmed that male bowhead whales emit complex acoustic songs spanning frequencies from 20 Hz to 5 kHz, repeating cyclical themes every 45 to 90 seconds throughout continuous polar darkness." What is the upper acoustic frequency emitted by these bowhead whales?', '[{"text":"20 Hz","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"5 kHz (5,000 Hz)","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"90 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"45 Hz","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting upper bounds in frequency ranges from marine acoustics literature.', 'Look at the range "from 20 Hz to ...".', 1.55, 0.4, 0.25, true, 0, 'ICSE Class 6 English Language Examination')
ON CONFLICT (scenario_code) DO UPDATE SET
  subject = EXCLUDED.subject,
  competency = EXCLUDED.competency,
  developmental_band = EXCLUDED.developmental_band,
  difficulty = EXCLUDED.difficulty,
  prompt = EXCLUDED.prompt,
  options = EXCLUDED.options,
  learning_objective = EXCLUDED.learning_objective,
  hint = EXCLUDED.hint,
  irt_a = EXCLUDED.irt_a,
  irt_b = EXCLUDED.irt_b,
  irt_c = EXCLUDED.irt_c,
  is_active = EXCLUDED.is_active,
  international_benchmark = EXCLUDED.international_benchmark;

INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-56-SYN-01', 'English Literacy', 'synthesis', '5-6', 'standard', 'Article 1: "Mangrove root systems dissipate ocean storm wave energy and trap coastal sediment." Article 2: "Communities situated behind intact coastal mangrove forests suffered 70% less structural inundation damage during Cyclone Vayu than communities with cleared shorelines." What synthesis unites both articles?', '[{"text":"Preserving natural mangrove buffers directly protects human settlements from destructive cyclonic waves.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Mangroves only thrive in areas subject to catastrophic hurricane strikes.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Coastal villages should replace mangrove forests with concrete seawalls.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Storm waves carry sediment away from mangrove estuaries into deep ocean trenches.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing ecological data with civic disaster mitigation outcomes.', 'Connect the wave-dissipating property of roots to the 70% reduction in storm damage.', 1.25, -0.5, 0.25, true, 0, 'Singapore Primary 5 Science & English'),
('ENG-56-SYN-02', 'English Literacy', 'synthesis', '5-6', 'standard', 'Text Alpha: "Ancient Caravans crossing the hyper-arid Rub'' al Khali depended on clusters of wild date palms as survival landmarks." Text Beta: "Hydrologists note that date palms can only germinate where subterranean aquifers lie within three meters of the desert surface." What deduction follows from cross-referencing these texts?', '[{"text":"Ancient travelers planted date palms to absorb excess desert floodwaters.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Date palms survive without any groundwater by absorbing ambient humidity.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Caravans avoided date palm groves due to the risk of quicksand.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Caravans relied on date palms because their presence signaled accessible freshwater underground.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Combining botanical hydrology with historical navigation practices.', 'Why would desert travelers look for a plant that only grows where water is close to the surface?', 1.3, -0.4, 0.25, true, 0, 'Cambridge Primary Stage 5 Synthesis'),
('ENG-56-SYN-03', 'English Literacy', 'synthesis', '5-6', 'standard', 'Source X: "Electric vehicle batteries require lithium, nickel, and cobalt, minerals mined in environmentally delicate ecosystems." Source Y: "Switching from internal combustion engines to electric transportation slashes operational tailpipe carbon emissions by up to 80%." How can these perspectives be integrated?', '[{"text":"Electric vehicles produce zero net environmental impact across their entire lifecycle.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Electric vehicles significantly reduce atmospheric emissions, though mineral extraction poses localized ecological challenges that require responsible lifecycle management.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Internal combustion engines are ecologically superior because mining is completely unnecessary.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Battery recycling eliminates all need for raw mineral extraction immediately.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing nuanced trade-offs across industrial and environmental texts.', 'Balance the clear reduction in carbon emissions with the environmental impact of mining.', 1.35, -0.3, 0.25, true, 0, 'US Common Core Grade 5 Nonfiction Synthesis'),
('ENG-56-SYN-04', 'English Literacy', 'synthesis', '5-6', 'standard', 'Report 1: "Regular physical exercise stimulates brain-derived neurotrophic factor (BDNF), a protein that accelerates the creation of new memory synapses." Report 2: "Students who engaged in 30 minutes of aerobic running before morning mathematics scored 18% higher on spatial memory tests." What comprehensive conclusion can be drawn?', '[{"text":"BDNF is only produced while students are seated in quiet classrooms.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Running makes students too fatigued to complete long mathematical problem sets.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Aerobic exercise promotes neural proteins that directly enhance cognitive retention and mathematical performance.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Spatial memory has no connection to neurological brain functions.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing biochemical mechanisms with real-world academic performance data.', 'Connect BDNF (synapse creation) with the higher test scores in spatial memory.', 1.3, -0.2, 0.25, true, 0, 'PIRLS Grade 5 Complex Synthesis'),
('ENG-56-SYN-05', 'English Literacy', 'synthesis', '5-6', 'advanced', 'Passage A: "The library''s archival budget decreased by 25% this year." Passage B: "Digital subscription fees for international research journals increased by 15%." Passage C: "The head librarian announced the cancellation of three physical print magazine contracts." What synthesized rationale explains the librarian''s decision?', '[{"text":"Digital journals were banned by the university board of directors.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The librarian dislikes physical magazines and prefers audiobooks exclusively.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Faced with reduced funding and rising digital costs, the library had to trim print expenditures to balance its operating budget.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The library received an anonymous cash donation that covered all subscription shortfalls.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing budget constraints and cost escalations into an administrative deduction.', 'Look at both the declining budget and the increasing costs.', 1.4, 0, 0.25, true, 0, 'Singapore Primary 6 PSLE Synthesis'),
('ENG-56-SYN-06', 'English Literacy', 'synthesis', '5-6', 'advanced', 'Study 1: "Nighttime light pollution disrupts nocturnal birds that navigate using the natural positions of stars." Study 2: "Cities that implemented amber-spectrum downward-shielded streetlights observed a 60% drop in disoriented migratory bird collisions." What holistic strategy is supported by this evidence?', '[{"text":"Targeted municipal lighting design can preserve celestial navigation cues and substantially protect migrating avian populations.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Cities should eliminate all public streetlights to completely restore pre-industrial darkness.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Nocturnal birds will eventually evolve biological radar to replace optical navigation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Amber lighting is exclusively used to accelerate vehicular traffic speed on highways.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing ecological disruption with civic technological interventions.', 'How does downward-shielded amber lighting solve the problem of star disruption?', 1.45, 0.1, 0.25, true, 0, 'Cambridge Secondary 1 Stage 6'),
('ENG-56-SYN-07', 'English Literacy', 'synthesis', '5-6', 'advanced', 'Perspective 1: "Autonomous crop-spraying drones reduce overall pesticide runoff by 40% through micro-targeted droplet dispensing." Perspective 2: "High initial equipment costs currently prevent smallholder farms from acquiring drone hardware without cooperative subsidies." What synthesis best represents the current status of agricultural drone technology?', '[{"text":"Pesticide runoff increases when drones replace manual backpack sprayers.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Drone technology is economically viable only for home gardeners with single-acre plots.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"While agricultural drones offer proven ecological advantages in chemical reduction, financial barriers require policy interventions for equitable adoption.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Smallholder farmers unanimously reject robotic farming techniques on philosophical grounds.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing ecological efficacy with economic feasibility constraints.', 'Recognize both the environmental benefit and the equipment cost barrier.', 1.4, 0.2, 0.25, true, 0, 'US Common Core Grade 6 Informational Synthesis'),
('ENG-56-SYN-08', 'English Literacy', 'synthesis', '5-6', 'olympiad', 'Historical Text: "The introduction of the Gutenberg movable type printing press in 1440 reduced book manufacturing costs by 80%." Cultural Text: "Between 1450 and 1500, literacy rates in Central European trading hubs rose from under 6% to over 28%." What cross-textual historical inference is most rigorously justified?', '[{"text":"The printing press was invented specifically to train merchant apprentices in bookkeeping arithmetic.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Technological automation in text production drastically lowered the economic barrier to written knowledge, fueling a rapid expansion in popular literacy.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Literacy rates increased exclusively because mandatory schooling was instituted by feudal kings.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Hand-copied illuminated manuscripts were completely destroyed by guild revolts.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing technological innovation with macro-sociological cultural transformation.', 'How does making books 80% cheaper directly cause more people to learn how to read?', 1.55, 0.3, 0.25, true, 0, 'Singapore Primary English Olympiad / PSLE Distinction'),
('ENG-56-SYN-09', 'English Literacy', 'synthesis', '5-6', 'olympiad', 'Medical Source A: "Antibiotic overuse in livestock agriculture creates selective evolutionary pressure, accelerating bacterial resistance strains." Medical Source B: "Hospitals report a 35% rise in multidrug-resistant bloodstream infections linked to agricultural pathogens." What imperative synthesis follows?', '[{"text":"Bacterial resistance strains cannot transfer from farm environments into urban clinical settings.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Antibiotics should be replaced with synthetic vitamins in human neonatal wards.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Curtailing routine non-therapeutic antibiotic use in food production is vital for preserving the efficacy of human clinical antimicrobials.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Livestock animals are biologically immune to antibiotic-resistant pathogens.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Connecting agricultural epidemiological practices with public health crises.', 'Connect animal antibiotic overuse to the surge in resistant human infections.', 1.6, 0.4, 0.25, true, 0, 'Cambridge Checkpoint Stage 6 Advanced'),
('ENG-56-SYN-10', 'English Literacy', 'synthesis', '5-6', 'olympiad', 'Theory 1: "The linguistic relativity hypothesis argues that the vocabulary and structure of a language shape how its speakers perceive time and spatial orientation." Case Study: "Speakers of Guugu Yimithirr, who describe spatial position strictly via cardinal points (north, south, east, west) rather than relative terms (left, right), possess extraordinary geographical navigation recall even in unfamiliar windowless rooms." How does the case study corroborate Theory 1?', '[{"text":"It suggests that windowless rooms cause psychological disorientation in all linguistic cohorts.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It proves that speakers of cardinal languages cannot understand left-handed tools.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It disproves the theory by showing navigation is purely dependent on atmospheric pressure.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It demonstrates that linguistic reliance on absolute cardinal markers reinforces subconscious internal spatial dead-reckoning.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing linguistic theory with empirical anthropological fieldwork.', 'How does always speaking in "north/south" train your brain to always know where north is?', 1.65, 0.5, 0.25, true, 0, 'ICSE Class 6 English Language Advanced'),
('ENG-56-EVL-01', 'English Literacy', 'evaluatingReflecting', '5-6', 'standard', '"No serious competitor would ever drink plain tap water when ElectroMax Sport can supercharge cellular hydration!" Which persuasive device does this advertising slogan deploy?', '[{"text":"A balanced, impartial comparison of electrolyte solubility.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Audited clinical laboratory results from medical university trials.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An appeal to elite status and peer exclusion: implying that non-users are unserious athletes.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A chronological historical survey of athletic hydration.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating rhetorical appeals to status and in-group exclusivity.', 'Notice the phrase "No serious competitor would ever...".', 1.2, -0.6, 0.25, true, 0, 'PIRLS Grade 5 Critical Literacy'),
('ENG-56-EVL-02', 'English Literacy', 'evaluatingReflecting', '5-6', 'standard', '"The old steam locomotive sighed a plume of white smoke, trembling wearily as if dreading the steep ascent over the mountain pass." What literary device is the author using, and to what effect?', '[{"text":"Scientific data documenting coal combustion pressure in iron boilers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Literal description of a biological organism climbing a hill.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Personification, to endow the mechanical engine with human feelings of fatigue and reluctance.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Hyperbolic exaggeration proving that steam engines possess beating hearts.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing the emotional resonance and purpose of personification in narrative prose.', 'Words like "sighed", "trembling wearily", and "dreading" are human traits applied to a machine.', 1.25, -0.5, 0.25, true, 0, 'Singapore Primary 5 English Literature'),
('ENG-56-EVL-03', 'English Literacy', 'evaluatingReflecting', '5-6', 'standard', 'Two accounts of a school bake sale: Account A (Student Council Treasurer): "We raised $450, exceeding our playground fundraising goal by 15%." Account B (School Neighbor): "The event caused heavy traffic congestion and litter on Maple Street." How do the authors'' roles influence their accounts?', '[{"text":"Account A is an outright fabrication because bake sales cannot generate profit.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Each author selectively highlights aspects that align with their distinct priorities—financial success versus community convenience.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Account B proves that school bake sales should be outlawed permanently.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Both accounts are identical in tone and provide the same statistical data.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Reflecting on authorial stance, perspective, and selective presentation of evidence.', 'Consider what matters most to the treasurer compared to what matters to a neighbor on the street.', 1.3, -0.4, 0.25, true, 0, 'Cambridge Primary Stage 5 Checkpoint'),
('ENG-56-EVL-04', 'English Literacy', 'evaluatingReflecting', '5-6', 'standard', 'An editorial argues: "Bicycle lanes on Main Street are an absolute catastrophe; my drive to work took four extra minutes on Tuesday morning!" What logical weakness undermines this argument?', '[{"text":"Overgeneralization based on a single personal inconvenience, ignoring broader urban safety and mobility benefits.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The author cited audited municipal vehicular traffic census records.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Bicycles are legally prohibited from traveling on paved asphalt roads.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The argument relies on excessive peer-reviewed economic research.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Identifying anecdotal bias and hasty generalization in opinion writing.', 'Can one person''s 4-minute delay prove that bike lanes are an "absolute catastrophe"?', 1.35, -0.3, 0.25, true, 0, 'US Common Core Grade 5 Critical Evaluation'),
('ENG-56-EVL-05', 'English Literacy', 'evaluatingReflecting', '5-6', 'advanced', '"The scientist acknowledged that while the laboratory synthesis yielded high purity, mass industrial scaling remained unproven." What does this statement reveal about the author''s tone and credibility?', '[{"text":"It reflects an attempt to deceive investors with inflated claims.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It demonstrates that the scientist is incompetent and lacks laboratory training.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It proves the chemical compound is completely useless for commercial medicine.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It conveys intellectual honesty and scientific objectivity by openly acknowledging real-world limitations.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Evaluating academic transparency, nuance, and author credibility.', 'A credible scientist admits limitations rather than exaggerating perfection.', 1.4, 0, 0.25, true, 0, 'Singapore Primary 6 PSLE Higher Order'),
('ENG-56-EVL-06', 'English Literacy', 'evaluatingReflecting', '5-6', 'advanced', '"The wildlife photographer spent fourteen freezing days in a snowblind without seeing a snow leopard, yet wrote: ''The mountain was not empty; it was patient.''" How does this concluding sentence reflect the photographer''s mindset?', '[{"text":"It expresses bitterness and anger toward elusive predators.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It illustrates deep reverence, humility, and philosophical acceptance of wild nature''s elusive independence.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"It indicates the photographer was hallucinating from extreme hypothermia.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It suggests the photographer intends to abandon wildlife photography.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Interpreting authorial reflection and philosophical depth in memoir prose.', 'Notice how the author reframes "empty" into "patient".', 1.45, 0.1, 0.25, true, 0, 'Cambridge Secondary 1 Stage 6 Literature'),
('ENG-56-EVL-07', 'English Literacy', 'evaluatingReflecting', '5-6', 'advanced', 'In an essay on space exploration, the author juxtaposes the billions spent on Mars orbiters with the millions of children lacking clean drinking water on Earth. What rhetorical objective is the author pursuing?', '[{"text":"Advocating for the total shutdown of all astronomical telescopes.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Proving that Mars soil contains potable liquid groundwater.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Challenging the ethical allocation of societal resources and questioning global priorities.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Arguing that rockets should be converted into municipal water tankers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing ethical juxtaposition and rhetorical inquiry in civic essays.', 'Why place billions for Mars right beside millions of thirsty children?', 1.4, 0.2, 0.25, true, 0, 'US Common Core Grade 6 Argumentative Reflection'),
('ENG-56-EVL-08', 'English Literacy', 'evaluatingReflecting', '5-6', 'olympiad', '"The historian remarked: ''To write history solely from the victors'' proclamations is like reconstructing an entire forest from the diary of a single lumberjack.''" What core methodological criticism is articulated through this analogy?', '[{"text":"Lumberjacks are unreliable observers of tree species.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Dominant institutional archives present a biased, incomplete narrative that erases the lived realities of the broader population.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Victors always tell the literal and complete truth in royal court chronicles.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Forest ecosystems cannot be studied using modern historical methods.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Critiquing historiographical bias and archival omission through metaphor.', 'What does a lumberjack care about compared to the whole forest?', 1.55, 0.3, 0.25, true, 0, 'Singapore Primary English Olympiad'),
('ENG-56-EVL-09', 'English Literacy', 'evaluatingReflecting', '5-6', 'olympiad', '"The editorial described the software company''s latest data collection policy as ''a benign modernization,'' masking the reality that user keystrokes were being monetized in real time." How does the author expose the corporation''s euphemism?', '[{"text":"By demonstrating that software updates cause keyboard hardware malfunctions.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By contrasting the harmless, reassuring corporate label with the invasive reality of continuous data commercialization.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"By endorsing the company''s transparent data ethics.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By proving that keystroke logging speeds up word processing typing.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing euphemistic corporate rhetoric and critical media literacy.', 'Compare "benign modernization" with "user keystrokes monetized in real time".', 1.6, 0.4, 0.25, true, 0, 'Cambridge Checkpoint Stage 6 Advanced'),
('ENG-56-EVL-10', 'English Literacy', 'evaluatingReflecting', '5-6', 'olympiad', '"When an author shifts suddenly from clinical third-person passive voice (''the decision was executed'') to intimate first-person active voice (''I signed the order''), what emotional transformation is imposed upon the reader?"', '[{"text":"Bureaucratic detachment is shattered, confronting the reader with inescapable individual moral accountability.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The author signals that the preceding events were completely fictional.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The narrative transitions from historical nonfiction into verse poetry.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The author demonstrates that grammar rules do not apply to political memoirs.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing rhetorical voice transitions and the attribution of moral responsibility.', 'How does going from "the decision was executed" to "I signed the order" feel different?', 1.65, 0.5, 0.25, true, 0, 'ICSE Class 6 English Literature Olympiad')
