INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-78-SYN-01', 'English Literacy', 'synthesis', '7-8', 'standard', 'Text 1: "Urban heat islands amplify nighttime temperatures by up to 6°C due to the thermal mass of concrete, brick, and asphalt." Text 2: "Cities that mandate extensive green living roofs and high-albedo reflective pavements record a 35% reduction in commercial HVAC cooling energy demand." What holistic conclusion connects these texts?', '[{"text":"Asphalt must be replaced exclusively with deep subterranean drainage tunnels.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Air conditioning units are the sole structural cause of urban heat retention.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Passive architectural and material interventions in urban surfaces can effectively mitigate heat island intensity while slashing municipal energy consumption.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Nighttime temperatures have no measurable bearing on metropolitan energy consumption.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing urban thermodynamic data with sustainable architectural policy.', 'Connect the heat-absorbing concrete in Text 1 with the living roofs/albedo in Text 2.', 1.35, 0.2, 0.25, true, 0, 'Cambridge Lower Secondary Stage 8 Synthesis'),
('ENG-78-SYN-02', 'English Literacy', 'synthesis', '7-8', 'standard', 'Study Alpha: "Microplastic particles under 50 micrometers are ingested by pelagic zooplankton." Study Beta: "Zooplankton form the primary trophic foundation for juvenile herring and mackerel, which are subsequently consumed by apex predatory tuna and humans." What overarching food-web deduction is established?', '[{"text":"Zooplankton populations expand rapidly when feeding on industrial polyester fibers.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Apex predatory tuna are biologically equipped to metabolize synthetic petroleum plastics into protein.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Microplastic pollution bioaccumulates and biomagnifies upward through trophic marine levels, ultimately threatening human nutritional chains.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Microplastics remain permanently confined to seabed sediment layers without entering fauna.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Tracing ecological contamination across multiple trophic levels.', 'Follow the chain: plastic -> zooplankton -> small fish -> tuna -> humans.', 1.35, 0.1, 0.25, true, 0, 'Singapore Secondary 2 English & Science'),
('ENG-78-SYN-03', 'English Literacy', 'synthesis', '7-8', 'standard', 'Economic Ledger: "Raw copper prices rose 45% due to supply chain mine strikes in the Andes." Industrial Bulletin: "Manufacturer Q shifted its residential electrical wiring lines from copper core to copper-clad aluminum alloy." What synthesized explanation accounts for Manufacturer Q''s engineering transition?', '[{"text":"Manufacturer Q redesigned product materials to substitute cheaper composite metals in response to soaring raw copper costs.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Aluminum is a superior electrical conductor compared to pure copper in all industrial environments.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Andean copper mines produce only aluminum alloy ore.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The government mandated that all copper must be preserved for sculpture monuments.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing macroeconomic commodity spikes with industrial material substitution.', 'Why would a manufacturer use copper-clad aluminum right when copper prices shoot up 45%?', 1.4, 0.3, 0.25, true, 0, 'US Common Core Grade 8 Informational'),
('ENG-78-SYN-04', 'English Literacy', 'synthesis', '7-8', 'standard', 'Botanical Observation: "Epiphytic orchids possess specialized spongy roots (velamen) that absorb ambient water vapor directly from humid air." Climatological Data: "Cloud forest deforestation caused a 25% drop in local ambient relative humidity over five years." What will be the consequence for indigenous cloud forest orchids?', '[{"text":"Orchid flowering cycles will accelerate because sunlight is increased.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The orchids will immediately grow deep terrestrial taproots into the bedrock.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The orchids will suffer severe hydration stress and population decline because their aerial root mechanisms require high ambient humidity.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The velamen tissue will transform into photosynthetic broad leaves.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing physiological botanical mechanisms with microclimate degradation.', 'If orchids get water from humidity, what happens when deforestation dries out the air?', 1.4, 0.2, 0.25, true, 0, 'ICSE Class 8 English & Biology'),
('ENG-78-SYN-05', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Document 1: "The 1883 eruption of Krakatoa injected over 20 million tons of sulfur aerosols into the stratosphere." Document 2: "Global meteorological stations recorded an average planetary surface temperature drop of 1.2°C during 1884, alongside vivid crimson sunsets recorded by painters across Europe." What synthesis bridges these physical and artistic phenomena?', '[{"text":"Stratospheric sulfate aerosols scattered solar radiation globally, causing both physical atmospheric cooling and optical scattering that altered sunset aesthetics worldwide.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Volcanic lava flows warmed European rivers and induced widespread psychological delirium among painters.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Crimson sunsets were caused by coal-burning factories in London rather than Krakatoa.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The temperature drop proved that volcanic eruptions halt planetary greenhouse gas cycles entirely.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing volcanological aerosol dynamics with historical climatology and art history.', 'How do sulfur aerosols in the high atmosphere cause both cooling and reddish skies?', 1.45, 0.4, 0.25, true, 0, 'Cambridge Secondary Checkpoint Stage 8'),
('ENG-78-SYN-06', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Source A: "Acoustic noise from commercial maritime shipping overlaps with the low-frequency vocalization bandwidth of baleen whales (10 Hz to 200 Hz)." Source B: "Endocrinological assays of whale blubber demonstrate a 60% surge in stress hormone glucocorticoids in shipping corridors." What unified conclusion is established?', '[{"text":"Low-frequency shipping sounds improve whale echolocation acuity during oceanic hunting.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Whales deliberately alter their migratory routes to escort commercial container vessels.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Glucocorticoid surges indicate that whales enjoy swimming alongside cargo ship propeller wakes.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Anthropogenic maritime acoustic pollution directly masks vital whale communication, inducing chronic physiological stress.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing anthropogenic acoustic data with marine biological endocrinology.', 'Connect frequency overlap (communication masking) with high stress hormones.', 1.5, 0.5, 0.25, true, 0, 'Singapore Secondary 2 Express Synthesis'),
('ENG-78-SYN-07', 'English Literacy', 'synthesis', '7-8', 'advanced', 'Theory: "The spacing effect demonstrates that distributed review sessions over time yield significantly superior long-term memory retention compared to massed cramming." Experiment: "Cohort A studied 10 hours in a single Saturday; Cohort B studied 2 hours every other day for 5 days. Tested 30 days later, Cohort B remembered 74% of the vocabulary, while Cohort A remembered 28%." How does the experimental data corroborate the theory?', '[{"text":"It demonstrates that total studying time is the sole determinant of retention regardless of schedule.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It quantitatively proves that distributed spacing creates more durable synaptic memory traces than equivalent time spent in massed cramming.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"It shows that vocabulary acquisition is biologically impossible over weekend study blocks.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"It proves that Cohort A was composed of students with lower baseline cognitive capacity.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing cognitive psychological theory with empirical quantitative retention tests.', 'Compare equal study time (10 hours) distributed vs crammed.', 1.5, 0.6, 0.25, true, 0, 'US Common Core Grade 8 Research Synthesis'),
('ENG-78-SYN-08', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Linguistic Text: "Old English (circa 800 CE) utilized complex inflectional grammatical cases and grammatical gender." Historical Text: "Following the 1066 Norman Conquest, Old French became the prestige language of royal administration, while Anglo-Saxon commoners and Scandinavian settlers interacted daily in multilingual trade marketplaces." What synthesized sociolinguistic mechanism explains the subsequent loss of complex inflections in Middle English?', '[{"text":"Grammatical gender was abolished by ecclesiastical decree from the Archbishop of Canterbury.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The Norman kings passed strict penal codes making the use of Old English inflectional suffixes a capital offense.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Everyday pragmatic communication across diverse linguistic populations favored structural leveling and simplified morphological endings in favor of rigid word order.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Old English was preserved with zero structural modifications inside monastic scriptoria.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing historical sociolinguistics, contact linguistics, and morphological leveling.', 'When speakers of different languages must trade daily, what happens to complex word endings?', 1.6, 0.8, 0.25, true, 0, 'Singapore English Olympiad Junior'),
('ENG-78-SYN-09', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Agricultural Report: "Continuous mono-cropping of corn depletes bioavailable soil nitrogen by 30% annually." Microbiology Study: "Legumes establish symbiotic root nodules with Rhizobium bacteria, converting atmospheric dinitrogen into mineral ammonium." Traditional Agronomy: "Mesoamerican farmers planted maize alongside beans and squash in polycultural ''Three Sisters'' guilds." What scientific rationale validates the traditional Three Sisters guild?', '[{"text":"The nitrogen-fixing legume beans naturally replenish the essential nitrogen exhausted by nutrient-hungry maize, sustaining long-term soil fertility.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Squash leaves absorb groundwater and pump it into the roots of surrounding cornstalks.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Maize produces atmospheric dinitrogen gas that kills root-dwelling Rhizobium bacteria.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Polycultural guilds are practiced purely for visual aesthetic harmony during festival harvest seasons.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing biogeochemical nutrient cycles with historical indigenous agronomy.', 'Connect corn''s nitrogen depletion with bean nodules fixing nitrogen.', 1.65, 0.9, 0.25, true, 0, 'Cambridge Secondary Checkpoint Olympiad Tier'),
('ENG-78-SYN-10', 'English Literacy', 'synthesis', '7-8', 'olympiad', 'Physics Postulate: "Conservation of angular momentum dictates that as a rotating body''s mass concentrates closer to its axis of rotation, its rotational velocity must increase." Astronomical Observation: "When a massive dying star collapses from a radius of 1,000,000 km into a dense neutron star with a radius of only 12 km, its spin period accelerates from months into milliseconds." How does the astronomical observation substantiate the physics postulate?', '[{"text":"The observation disproves the postulate because stellar mass is destroyed during gravitational collapse.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Neutron stars possess magnetic fields that physically drag nearby space-time into rotation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Dying stars absorb rotational energy from colliding neighboring galaxies during supernova collapse.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"The dramatic reduction in radius contracts stellar moment of inertia, forcing extreme spin acceleration to conserve total angular momentum.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing foundational physical conservation laws with astrophysics phenomena.', 'Think of an ice skater pulling in their arms: smaller radius -> much faster spin.', 1.7, 1, 0.25, true, 0, 'ICSE Class 8 Science & English Olympiad'),
('ENG-78-EVL-01', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', '"The historian repeatedly describes the medieval parchment manuscript as ''whispering forgotten heresies from beneath centuries of dust.''" What stylistic resonance is achieved by this personification?', '[{"text":"It casts doubt on the archaeological authenticity of the parchment provenance.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It provides literal acoustic decibel measurements of parchment vibration.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It proves that the manuscript was copied by multiple illiterate scribes.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It endows the physical artifact with mysterious agency, historical intimacy, and suppressed ideological drama.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Evaluating the aesthetic and dramatic functions of personification in historical prose.', 'How does describing a book as "whispering forgotten heresies" make the reader feel?', 1.3, 0.1, 0.25, true, 0, 'Cambridge Lower Secondary Checkpoint Stage 8'),
('ENG-78-EVL-02', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', 'A pharmaceutical advertisement claims: "9 out of 10 doctors surveyed recommend NeuroBoost for morning fatigue!" What critical question must a discerning reader ask to evaluate this claim?', '[{"text":"How many total doctors were surveyed, how were they selected, and was the survey funded by the manufacturer?","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"What color is the packaging of the NeuroBoost capsule box?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Can NeuroBoost be consumed with carbonated beverages?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Are the doctors legally licensed to operate motor vehicles?","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating sample selection bias, statistical validity, and commercial conflicts of interest.', 'If only 10 cherry-picked company doctors were asked, does 9 out of 10 mean anything?', 1.35, 0.2, 0.25, true, 0, 'US Common Core Grade 8 Critical Evaluation'),
('ENG-78-EVL-03', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', '"The senator began her speech on the national debt by recalling her grandfather''s tiny general store and how he balanced his physical ledger book by candlelight every Saturday night." What rhetorical strategy is being employed here?', '[{"text":"An objective presentation of audited central bank currency reserves.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A technical econometric breakdown of foreign bond interest yield curves.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An appeal to folk nostalgia and homespun common sense to simplify a complex macroeconomic issue into an emotionally relatable moral allegory.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A formal refutation of commercial bankruptcy jurisprudence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing folksy nostalgic anecdotes as persuasive framing devices in politics.', 'Why talk about a grandfather''s tiny ledger book when debating a multi-trillion national debt?', 1.4, 0.3, 0.25, true, 0, 'Singapore Secondary 2 Express English'),
('ENG-78-EVL-04', 'English Literacy', 'evaluatingReflecting', '7-8', 'standard', 'An author introduces a villain with: "His smile was impeccable, gleaming like polished porcelain, but it never reached the cold, calculating slate of his eyes." What psychological insight does this imagery implant in the reader?', '[{"text":"Duality and deceit: an outward veneer of charm concealing an underlying predatory and unfeeling disposition.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A clinical dental diagnosis of healthy tooth enamel.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A sympathetic portrayal of a character suffering from eye strain.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An objective appraisal of stone carving craftsmanship.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing facial imagery and emotional dissonance in character characterization.', 'Contrast the gleaming smile with the cold, calculating eyes.', 1.35, 0.2, 0.25, true, 0, 'ICSE Class 8 English Literature'),
('ENG-78-EVL-05', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', '"The op-ed writer opens: ''Either we ban all artificial intelligence development immediately, or we surrender our humanity to silicon overlords.''" Which logical fallacy undermines this polemic?', '[{"text":"Ad hominem attack against individual software developers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"False dilemma (bifurcation): reducing a multifaceted regulatory issue into two extreme, mutually exclusive choices.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Circular reasoning that repeats the premise as the conclusion.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Post hoc ergo propter hoc causal confusion.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Identifying false dilemmas and black-and-white fallacies in argumentative discourse.', 'Are those really the only two possible choices for AI?', 1.45, 0.5, 0.25, true, 0, 'Cambridge Secondary Stage 8 Argumentation'),
('ENG-78-EVL-06', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', 'In reviewing a contemporary novel, a critic writes: "The author mistakes relentless misery for profound artistry, piling misfortune upon catastrophe without providing a shred of thematic illumination." What is the essence of this critique?', '[{"text":"The author should have written a cheerful children''s comedy instead.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The novel has too few pages to properly develop its characters.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Unrelieved gratuitous suffering does not equate to substantive philosophical or literary insight.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The book contains grammatical syntax errors in its dialogue.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating literary criticism and the distinction between melodrama and artistic depth.', 'What is the critic saying about piling on sadness without "thematic illumination"?', 1.5, 0.6, 0.25, true, 0, 'Singapore Secondary 2 Express Literature'),
('ENG-78-EVL-07', 'English Literacy', 'evaluatingReflecting', '7-8', 'advanced', '"The travel essay concludes: ''We traveled ten thousand miles to photograph pristine wilderness, only to discover our own footprints permanently pressed into the tundra.'' What reflective realization does this closing sentence impart?"', '[{"text":"Regret over failing to wear proper thermal hiking boots.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An ironic awareness of human ecological complicity: the very act of seeking untouched wilderness inevitably alters and intrudes upon it.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A practical realization that tundra soil requires paving.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Anger that other tourists arrived at the summit first.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Reflecting on situational irony and human complicity in travel journalism.', 'Notice the irony of going to see "untouched" land only to find you left your footprints on it.', 1.5, 0.5, 0.25, true, 0, 'US Common Core Grade 8 Reflective Reading'),
('ENG-78-EVL-08', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"The political speechwriter skillfully employed anaphora, opening six consecutive sentences with ''We shall not falter...'' What psychological momentum does this repetitive rhetorical cadence generate?"', '[{"text":"Evidence that the speaker lacked sufficient varied vocabulary to compose prose.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Linguistic fatigue and confusion regarding grammatical sentence syntax.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Cumulative emotional resolve and rhythmic inevitability, rallying collective resolve through rhythmic linguistic reinforcement.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"An attempt to disguise factual inaccuracies in the accompanying statistical appendix.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating anaphora and rhythmic structural rhetoric in public oratory.', 'What does repeating a strong phrase six times do to a listener''s feelings?', 1.6, 0.8, 0.25, true, 0, 'Singapore English Olympiad Junior'),
('ENG-78-EVL-09', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"To call the corporation''s mass laying off of three thousand factory workers ''a workforce right-sizing optimization'' is to sanitize economic devastation with the clinical dialect of corporate technocracy." What authorial stance is revealed by this indictment?', '[{"text":"A technical defense of executive stock option vesting structures.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Enthusiastic support for corporate managerial efficiency.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Indifference toward labor union contract negotiations.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Fierce moral indignation against dehumanizing corporate euphemisms that disguise human suffering.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Deconstructing technocratic euphemisms and analyzing authorial outrage.', 'Notice words like "sanitize economic devastation" and "clinical dialect".', 1.65, 0.9, 0.25, true, 0, 'Cambridge Checkpoint Stage 8 Distinction Tier'),
('ENG-78-EVL-10', 'English Literacy', 'evaluatingReflecting', '7-8', 'olympiad', '"When the satirist praises the dystopian government for ''magnanimously rationing electricity so citizens can rediscover the romance of darkness,'' what rhetorical mechanism is operating?"', '[{"text":"A scientific treatise on the circadian sleep benefits of complete darkness.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Literal praise for municipal renewable energy conservation.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Sarcastic irony: professing admiration for an authoritarian failure to expose its absurdity and oppression.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Historical nostalgia for medieval pre-electric societies.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing sustained satirical irony and authorial intent in dystopian literature.', 'Is the author truly romanticizing an authoritarian blackout, or mocking it?', 1.7, 1, 0.25, true, 0, 'ICSE Class 8 English Literature Advanced')
ON CONFLICT (scenario_code) DO UPDATE SET
  subject = EXCLUDED.subject,
  competency = EXCLUDED.competency,
  developmental_band = EXCLUDED.developmental_band,
  difficulty = EXCLUDED.difficulty,
  prompt = EXCLUDED.prompt,
  options = EXCLUDED.options,
  learning_objective = EXCLUDED.learning_objective,
  hint = EXCLUDED.hint,
  irt_a = EXCLUDED.irt_a,
  irt_b = EXCLUDED.irt_b,
  irt_c = EXCLUDED.irt_c,
  is_active = EXCLUDED.is_active,
  international_benchmark = EXCLUDED.international_benchmark;

INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-910-UND-01', 'English Literacy', 'understanding', '9-10', 'standard', '"The biographer does not romanticize the statesman''s triumphs; rather, she dissects his compromises with the forensic detachment of an anatomist." What characterizes the biographer''s intellectual style?', '[{"text":"Unsentimental, rigorous, and analytically critical examination.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Hagiographic celebration of patriotic martyrdom.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Superficial sensationalism focused on court intrigue.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Nostalgic praise for obsolete diplomatic conventions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing tone, register, and authorial detachment in high-level biographical prose.', 'Notice words like "forensic detachment" and "dissects compromises".', 1.3, 0.3, 0.25, true, 0, 'IGCSE English Language / Cambridge O-Level'),
('ENG-910-UND-02', 'English Literacy', 'understanding', '9-10', 'standard', '"The judicial majority held that freedom of expression is not an absolute sovereign license, but a situated right bounded by the state''s compelling interest in preventing imminent incitement to violence." How does the court define the boundary of free speech?', '[{"text":"As an unlimited personal entitlement that supersedes all public safety laws.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As a vital but conditional right that may be curtailed when speech creates an immediate threat of unlawful violence.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"As a privilege granted exclusively to licensed journalistic media organizations.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an obsolete constitutional principle that has no modern relevance.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing complex constitutional legal prose and conditional rights.', 'Look for the boundary: "bounded by the state''s compelling interest in preventing imminent incitement".', 1.35, 0.4, 0.25, true, 0, 'ICSE Class 10 English Language'),
('ENG-910-UND-03', 'English Literacy', 'understanding', '9-10', 'standard', '"In describing the sprawling megalopolis as ''a voracious metabolic engine ingesting rivers of freshwater and exhaling plumes of toxic carbon,'' what ecological paradigm is the author deploying?"', '[{"text":"A celebration of urban architectural density and civil engineering mastery.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An industrial metabolism paradigm, framing the modern city as an organism with consumptive and excretory resource flows.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A literal claim that asphalt highways possess biological lungs.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A historical economic treatise on pre-industrial river transportation.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting ecological paradigms and metabolic metaphors in urban studies essays.', 'Notice: ingesting freshwater, exhaling carbon, "metabolic engine".', 1.4, 0.5, 0.25, true, 0, 'Singapore MOE Secondary 4 O-Level English'),
('ENG-910-UND-04', 'English Literacy', 'understanding', '9-10', 'standard', '"The novel''s narrator maintains an ironic distance, recounting his family''s catastrophic bankruptcy with the dry amusement of a spectator watching a badly rehearsed farce." What does this tonal dissonance signify?', '[{"text":"Genuine financial joy at being liberated from material wealth.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A psychological coping defense: using cynical levity to shield himself from the raw trauma of domestic ruin.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Total ignorance regarding the reality of debt and insolvency.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A technical theatrical critique of amateur stage productions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing tonal dissonance as a psychological coping mechanism in first-person narrative.', 'Why would someone narrate their own ruin like it''s a "badly rehearsed farce"?', 1.35, 0.4, 0.25, true, 0, 'US Common Core Grade 10 Reading Literature'),
('ENG-910-UND-05', 'English Literacy', 'understanding', '9-10', 'standard', '"The epistemologist cautioned that our intuitive perception of time as an unbroken flowing river is an evolutionary cognitive convenience, not an ontological feature of physical space-time." What distinction is being drawn?', '[{"text":"Between ancient mythological rivers and modern navigational canals.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Between liquid hydrological flows and mechanical clock escapements.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Between the brain''s adaptive subjective experience of time and the actual mathematical reality of the physical universe.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Between human memory capacity and computer hard drive storage.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Distinguishing ontological reality from evolutionary cognitive adaptation.', 'Contrast "cognitive convenience" (how the mind experiences it) with "ontological feature" (what is physically true).', 1.4, 0.5, 0.25, true, 0, 'CBSE Class 10 English Communicative'),
('ENG-910-UND-06', 'English Literacy', 'understanding', '9-10', 'advanced', '"The essay posits that modern commodification of art reduces the museum from a temple of contemplative aesthetic communion to a transactional gallery of speculative financial assets." What societal transformation does this critique diagnose?', '[{"text":"A legal requirement that all museums operate as private commercial banks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An increase in religious visitors attending art galleries for prayer.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The total obsolescence of oil painting in the face of digital photography.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The subordination of authentic artistic spiritual and cultural value to capitalist investment and elite status display.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Deconstructing critical cultural theory regarding the financialization of art.', 'Contrast "temple of contemplative aesthetic communion" with "transactional gallery of financial assets".', 1.45, 0.7, 0.25, true, 0, 'Cambridge IGCSE Literature in English'),
('ENG-910-UND-07', 'English Literacy', 'understanding', '9-10', 'advanced', '"The cultural theorist argues that nostalgia is not an innocent wistfulness for the past, but an active ideological weapon that rewrites history to legitimize contemporary exclusion." How is nostalgia redefined here?', '[{"text":"As a potent political instrument that curates a mythic golden age to justify current sociopolitical oppression.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"As an incurable neurological disease affecting elderly citizens.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an artistic aesthetic limited exclusively to Victorian interior decorating.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"As an objective chronological method for cataloging museum antiquities.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting critical ideological definitions of collective memory and nostalgia.', 'Look at what nostalgia does politically: "rewrites history to legitimize contemporary exclusion".', 1.5, 0.8, 0.25, true, 0, 'Singapore Secondary 4 Express / GCE O-Level'),
('ENG-910-UND-08', 'English Literacy', 'understanding', '9-10', 'advanced', '"The author describes the desert landscape as ''indifferent rather than cruel,'' insisting that projecting malevolence onto arid dunes is merely human vanity unable to accept a universe that does not care about its survival." What philosophical realization is articulated?', '[{"text":"Cosmic indifference: nature operates by physical laws entirely detached from human moral narratives or emotional desires.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Deserts actively conspire to punish travelers who violate ancient tribal customs.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Human survival is guaranteed in any extreme environment through sheer willpower.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Arid climates are biologically superior to temperate deciduous forests.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing cosmic indifference and the pathetic fallacy in existential literature.', 'Notice: "indifferent rather than cruel", refusing to project malevolence.', 1.5, 0.9, 0.25, true, 0, 'US AP English Language Entry Diagnostic'),
('ENG-910-UND-09', 'English Literacy', 'understanding', '9-10', 'olympiad', '"The structuralist literary critic asserts that the protagonist''s tragedy was not forged in the crucible of his fatal moral flaw (hamartia), but was mechanically predetermined by the socioeconomic constraints of the narrative architecture." How does this interpretation challenge classical Aristotelian poetics?', '[{"text":"It reaffirms that individual ethical choices are the sole driving force of dramatic tragedy.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It displaces individual moral agency and personal fault in favor of systemic, deterministic societal structures.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"It argues that ancient Greek tragedies were written exclusively for comedic entertainment.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It proves that plays must have five acts to maintain dramatic tension.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Contrasting classical individual hamartia with structuralist socioeconomic determinism.', 'Notice the shift from personal moral flaw to narrative/socioeconomic predetermination.', 1.6, 1.1, 0.25, true, 0, 'Singapore Secondary English Olympiad / National Team Trials'),
('ENG-910-UND-10', 'English Literacy', 'understanding', '9-10', 'olympiad', '"The political essayist warns that when totalitarian regimes monopolize language through state-sanctioned euphemisms, they do not merely censor dissenting speech—they dismantle the cognitive conceptual vocabulary required to formulate dissenting thoughts." What profound mechanism of control is identified?', '[{"text":"Enforcing compulsory attendance at patriotic military rallies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Physical imprisonment of political dissidents in remote penal colonies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Linguistic determinism: restricting language to preemptively eradicate the mental capacity for critical rebellion.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Banning all import tariffs on foreign consumer electronics.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing Orwellian linguistic hegemony and the constriction of cognitive conceptual horizons.', 'Think about Orwell''s Newspeak: if there are no words for freedom, can people think of freedom?', 1.65, 1.2, 0.25, true, 0, 'Cambridge IGCSE Distinction / IB Middle Years Program'),
('ENG-910-LOC-01', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Food Safety Regulatory Dossier: "Section 4.2: Plasticizer Additive DEHP is strictly prohibited in dairy contact packaging unless the migration coefficient into aqueous food simulants remains below 0.05 mg/dm² over a standardized 10-day test cycle at 40°C." What threshold must DEHP satisfy to be legally permissible?', '[{"text":"Total absence of chemical migration over a 30-day cycle at room temperature.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Migration coefficient strictly below 0.05 mg/dm² under standard 10-day, 40°C conditions.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"A concentration exceeding 0.5 mg/dm² in lipid food simulants.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Thermal stability up to 100°C regardless of packaging contact.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting precise biochemical migration standards and testing conditions from regulatory codes.', 'Check the exact number (0.05 mg/dm²), duration (10 days), and temperature (40°C).', 1.35, 0.2, 0.25, true, 0, 'Cambridge O-Level Informational Text'),
('ENG-910-LOC-02', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Nanotechnology Safety Guidelines: "Carbon nanotube dispersion handling requires a Class II Type B2 biosafety cabinet with 100% exhaust through dual HEPA filtration. Minimum face velocity must be calibrated to 0.53 m/s ± 0.02 m/s." What is the mandated face velocity for the cabinet?', '[{"text":"10 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"100 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2.0 m/s ± 0.5 m/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.53 m/s ± 0.02 m/s","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning occupational health manuals for specific aerodynamic velocity tolerances.', 'Look for "face velocity must be calibrated to".', 1.35, 0.3, 0.25, true, 0, 'Singapore Secondary 3 Express'),
('ENG-910-LOC-03', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Patent Disclosure Statement: "Claim 1: The solar thermoelectric device utilizes bismuth telluride nanowires having an average diameter between 15 nm and 25 nm and an electrical conductivity greater than 1.2 × 10⁵ S/m at 300 K." What is the required diameter range for the nanowires?', '[{"text":"Greater than 1.2 × 10⁵ nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Between 15 nm and 25 nm","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"300 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Exactly 1 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting dimensional nanoscale parameters from formal patent claims.', 'Scan for the word "diameter" and note the nanometer range.', 1.4, 0.3, 0.25, true, 0, 'US Common Core Grade 10 Technical Reading'),
('ENG-910-LOC-04', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Clinical Trial Pharmacokinetics: "In Cohort 3, the half-life (t1/2) of mAb-71 was determined to be 18.4 days, while renal clearance averaged 2.1 mL/h. Neutralizing anti-drug antibodies (ADAs) were detected in 3 out of 42 subjects at Day 56." In what fraction of subjects were neutralizing antibodies detected at Day 56?', '[{"text":"All 42 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"18.4 out of 100 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2.1 out of 42 subjects","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"3 out of 42 subjects","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating specific immunogenicity incidence rates in clinical cohort summaries.', 'Find the sentence mentioning "anti-drug antibodies (ADAs)".', 1.4, 0.4, 0.25, true, 0, 'ICSE Class 10 English Language'),
('ENG-910-LOC-05', 'English Literacy', 'locatingInformation', '9-10', 'standard', 'Urban Zoning Statute: "Mixed-Use Commercial Zone C-4 mandates a Floor Area Ratio (FAR) not exceeding 4.5. Maximum building height is capped at 65 meters, with a minimum 8-meter setback from primary road centrelines for all structures exceeding 30 meters." What is the maximum permissible FAR?', '[{"text":"30 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"65 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"8 meters","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Not exceeding 4.5","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Extracting precise regulatory ratios from municipal zoning ordinances.', 'Look directly for "Floor Area Ratio (FAR)".', 1.35, 0.3, 0.25, true, 0, 'CBSE Class 10 English Language'),
('ENG-910-LOC-06', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'International Environmental Treaty: "Under Annex II of the Minamata Convention on Mercury, parties shall prohibit the manufacturing, import, and export of dental amalgam containing over 50% mercury by mass starting January 1, 2030, unless an exemption for pediatric encapsulation is filed before July 1, 2028." What is the final exemption filing date?', '[{"text":"January 1, 2030","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Before July 1, 2028","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"After 50 years","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"July 1, 2032","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Disentangling prohibition enforcement dates from preliminary exemption filing deadlines.', 'Distinguish between the 2030 prohibition date and the 2028 exemption deadline.', 1.45, 0.6, 0.25, true, 0, 'Cambridge IGCSE English First Language'),
('ENG-910-LOC-07', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'Deep Space Mission Trajectory: "The gravitational slingshot maneuver around Jupiter will impart an orbital delta-v of 5.8 km/s, adjusting perihelion distance to 0.72 AU. Trajectory correction burn TCM-2 is scheduled for mission elapsed time MET +180 days with a thruster burn duration of 412 seconds." What is the duration of thruster burn TCM-2?', '[{"text":"0.72 AU","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"180 days","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"5.8 km/s","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"412 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning orbital mechanics mission timelines for exact engine burn durations.', 'Find the duration paired specifically with "TCM-2".', 1.5, 0.7, 0.25, true, 0, 'Singapore Secondary 4 Express / O-Level'),
('ENG-910-LOC-08', 'English Literacy', 'locatingInformation', '9-10', 'advanced', 'Semiconductor Fabrication Manual: "Photolithography process 7A operates at an extreme ultraviolet (EUV) wavelength of 13.5 nm. Mirror optics must be maintained in a vacuum below 10⁻⁷ Torr, with chamber hydrogen flow stabilized at 25 sccm to mitigate tin debris deposition." What vacuum pressure threshold is required?', '[{"text":"13.5 nm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Below 10⁻⁷ Torr","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"25 sccm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"7A Torr","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exponential scientific vacuum thresholds in advanced microelectronics literature.', 'Look for the pressure unit "Torr" and the exponential notation.', 1.5, 0.8, 0.25, true, 0, 'US Common Core Grade 10 Technical Evaluation'),
('ENG-910-LOC-09', 'English Literacy', 'locatingInformation', '9-10', 'olympiad', 'Constitutional Court Opinion: "The Appellate Bench held that while Article 19(1)(g) secures the right to practice any trade, reasonable restrictions under Article 19(6) permit mandatory licensing schemes if the licensing fee does not exceed 2% of annual net turnover and an appeal mechanism is adjudicated within 45 days." What is the maximum permitted licensing fee percentage?', '[{"text":"45% of gross profit","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Not exceeding 2% of annual net turnover","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"19% of operating revenue","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1% of net assets","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exact statutory financial limitations in complex judicial holdings.', 'Find the percentage limit associated with the "licensing fee".', 1.6, 1, 0.25, true, 0, 'Singapore English Olympiad Senior'),
('ENG-910-LOC-10', 'English Literacy', 'locatingInformation', '9-10', 'olympiad', 'Biomedical Proteomics Paper: "Mass spectrometry analysis identified phosphorylation at serine residue Ser-342 of protein Kinase-B, which increased enzymatic kinase activity by 4.2-fold compared to wild-type, whereas mutation to alanine (Ser342Ala) eliminated phosphorylation and reduced baseline activity by 85%." What effect did the Ser342Ala mutation have on baseline enzymatic activity?', '[{"text":"Doubled phosphorylation rate","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Increased activity by 4.2-fold","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Reduced baseline activity by 85%","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Elevated kinase expression by 342%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting exact quantitative phenotypic outcomes of specific amino acid point mutations.', 'Check specifically what the mutation (Ser342Ala) did, not the original phosphorylation.', 1.65, 1.1, 0.25, true, 0, 'Cambridge IGCSE / GCE O-Level Olympiad Rank')
ON CONFLICT (scenario_code) DO UPDATE SET
  subject = EXCLUDED.subject,
