INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-910-SYN-01', 'English Literacy', 'synthesis', '9-10', 'standard', 'Perspective Alpha: "Generative linguistic AI expands cognitive productivity by automating boilerplate formulation and syntactical formatting." Perspective Beta: "Cognitive offloading to automated text generators atrophies the neural circuits responsible for deep semantic synthesis and independent critical reasoning." How do these viewpoints reconcile in an analytical synthesis?', '[{"text":"Both authors agree that writing has no connection to intellectual development.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"While automated tools expedite mechanical drafting, deliberate unassisted writing remains essential for cultivating deep analytical intellect.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Perspective Alpha proves that human critical thinking is entirely obsolete.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Perspective Beta argues that software tools should be outlawed by global decree.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing conflicting positions on artificial intelligence and cognitive offloading.', 'Acknowledge the productivity benefits of AI while preserving the irreplaceable need for critical thinking.', 1.4, 0.4, 0.25, true, 0, 'Cambridge IGCSE English Language Synthesis'),
('ENG-910-SYN-02', 'English Literacy', 'synthesis', '9-10', 'standard', 'Study 1: "Marine phytoplankton generate roughly 50% of Earth''s atmospheric oxygen via oceanic photosynthesis." Study 2: "Ocean acidification and rising sea surface temperatures have induced a 1.5% annual decline in global phytoplankton biomass over the past four decades." What systemic planetary inference is justified?', '[{"text":"Terrestrial trees will automatically expand their oxygen output to compensate for ocean losses.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Anthropogenic marine warming and acidification threaten the foundational biological engine responsible for global oxygen generation.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Phytoplankton thrive and multiply rapidly in warmer, acidic ocean waters.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Atmospheric oxygen levels are completely independent of marine biological cycles.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing biogeochemical oceanography with global climate destabilization.', 'Connect the role of phytoplankton (50% oxygen) with their ongoing decline.', 1.4, 0.3, 0.25, true, 0, 'Singapore Secondary 4 Express English'),
('ENG-910-SYN-03', 'English Literacy', 'synthesis', '9-10', 'standard', 'Economic Report: "Automation and algorithmic trading now account for 78% of daily equity market liquidity." Sociological Review: "High-frequency flash crashes occur when autonomous algorithms execute simultaneous liquidation orders during localized volatility spikes." What synthesis connects these findings?', '[{"text":"Algorithmic trading has completely eliminated market volatility permanently.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Human floor traders are significantly faster at executing orders than fiber-optic algorithms.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"While algorithmic trading enhances daily transaction liquidity, synchronized automated decision-making introduces systemic risks of sudden catastrophic market instability.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Liquidation orders can only be authorized by federal central bankers.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing market liquidity mechanisms with algorithmic systemic vulnerabilities.', 'Weigh high daily liquidity against the systemic danger of sudden "flash crashes".', 1.45, 0.5, 0.25, true, 0, 'ICSE Class 10 Economics & English'),
('ENG-910-SYN-04', 'English Literacy', 'synthesis', '9-10', 'standard', 'Historical Account A: "The 1911 introduction of Henry Ford''s moving assembly line reduced chassis production time from 12 hours to 93 minutes." Labor History B: "Assembly-line workers reported severe psychological alienation and physical strain from extreme repetitive task specialization, leading to 380% annual turnover until Ford doubled daily wages to $5." What synthesis unifies both accounts?', '[{"text":"Repetitive labor specialization enhanced worker job satisfaction and creative autonomy.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Ford''s moving assembly line proved to be an economic failure that slowed car manufacturing.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Industrial efficiency gains through extreme mechanization created severe human labor strains that necessitated unprecedented wage concessions to stabilize the workforce.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Assembly-line techniques were abandoned across American manufacturing by 1915.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing technological productivity leaps with psychological labor alienation.', 'Connect the massive speedup with the extreme worker turnover and wage doubling.', 1.45, 0.4, 0.25, true, 0, 'US Common Core Grade 10 Synthesis'),
('ENG-910-SYN-05', 'English Literacy', 'synthesis', '9-10', 'advanced', 'Theory X: "Technological determinism claims that autonomous technological innovation is the primary causal driver transforming human culture and social institutions." Theory Y: "Social constructivism argues that human values, political choices, and economic institutions actively steer and shape which technologies are funded, developed, and deployed." How can a dialectical synthesis reconcile these theories?', '[{"text":"Both theories agree that pre-industrial societies were technologically superior.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Theory X is entirely correct, proving that human culture has zero impact on technological tools.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Theory Y proves that machinery operates strictly according to moral and legal guidelines.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Technology and society co-evolve reciprocally: social values shape technological inception, while deployed technologies subsequently reshape societal behaviors and structures.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Formulating a dialectical synthesis between opposing sociological paradigms.', 'Look for reciprocal co-evolution: society shapes tools, tools shape society.', 1.5, 0.7, 0.25, true, 0, 'Cambridge IGCSE First Language English'),
('ENG-910-SYN-06', 'English Literacy', 'synthesis', '9-10', 'advanced', 'Medical Source 1: "CRISPR-Cas9 somatic gene editing has cured patients of sickle-cell anemia by repairing the mutated beta-globin gene in blood stem cells." Bioethics Essay 2: "Germline genomic modifications alter inheritable DNA across future generations without the consent of unborn progeny, risking unforeseen off-target epigenetic mutations." What critical synthesis distinguishes somatic from germline editing?', '[{"text":"Somatic gene editing offers immediate therapeutic relief confined to an individual patient, whereas germline modification introduces multi-generational ethical and biological ramifications.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Somatic gene editing permanently alters every future descendant of the treated patient.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Germline editing is strictly prohibited because Cas9 enzymes cannot cut human DNA.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Both forms of gene therapy have been proven entirely free of any biological risk.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing clinical therapeutic efficacy with bioethical boundaries in gene editing.', 'Distinguish between treating an individual patient (somatic) vs altering inherited DNA (germline).', 1.55, 0.8, 0.25, true, 0, 'Singapore Secondary 4 O-Level Science & English'),
('ENG-910-SYN-07', 'English Literacy', 'synthesis', '9-10', 'advanced', 'Text Alpha: "Urban sprawl fragments natural forests into isolated island patches." Text Beta: "The theory of island biogeography demonstrates that smaller, isolated habitat patches experience exponentially higher extinction rates due to edge effects and inbreeding depression." What synthesized urban planning recommendation follows?', '[{"text":"Cities should concentrate heavy industrial factories inside forest fragments.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Forest fragments should be fully cleared to eliminate confusing edges for wildlife.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Island biogeography applies strictly to volcanic islands in the Pacific Ocean.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Urban master plans must incorporate continuous wildlife migration corridors that physically reconnect fragmented woodland islands.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing theoretical ecological biogeography with actionable urban landscape planning.', 'If isolated patches cause extinctions, how do wildlife corridors solve that problem?', 1.5, 0.7, 0.25, true, 0, 'CBSE Class 10 Environmental Literature'),
('ENG-910-SYN-08', 'English Literacy', 'synthesis', '9-10', 'olympiad', 'Linguistic Study: "Cognitive offloading through digital GPS navigation reduces hippocampal spatial mapping activity and deteriorates mental dead-reckoning." Anthropological Fieldwork: "Polynesian traditional wayfinders, navigating thousands of open-sea nautical miles via star paths, ocean swells, and avian flight vectors, exhibit significantly enlarged posterior hippocampal gray matter volume." What holistic neuro-cultural synthesis is established?', '[{"text":"Wayfinding is genetically encoded exclusively in Polynesian populations and cannot be learned.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Active reliance on environmental spatial processing physically cultivates neurological mapping infrastructure, whereas technological outsourcing leads to structural neural atrophy.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"GPS satellite signals emit microwave frequencies that damage brain tissue.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Hippocampal volume is completely fixed at birth and unaffected by environmental navigation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing cognitive neuroscience, neuroplasticity, and comparative cultural epistemology.', 'Notice how using your brain for navigation enlarges the hippocampus, while using GPS atrophies it.', 1.65, 1, 0.25, true, 0, 'Singapore English Olympiad Senior Division'),
('ENG-910-SYN-09', 'English Literacy', 'synthesis', '9-10', 'olympiad', 'Epistemology Paper: "Karl Popper''s falsificationism asserts that a hypothesis is scientific only if it makes empirical predictions that can be conclusively refuted by observation." Philosophy of Science: "Thomas Kuhn''s paradigm theory shows that during periods of ''normal science,'' researchers regularly dismiss anomalous data rather than abandon their reigning foundational paradigm." How do these two frameworks intersect in scientific sociology?', '[{"text":"Popper proves that scientists always immediately discard theories upon discovering a single error.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"While Popper articulates the normative logical ideal of how science ought to proceed, Kuhn describes the sociopsychological reality of how scientific communities actually behave.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Kuhn demonstrates that empirical observation has zero relevance to scientific advancement.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Both philosophers agree that scientific consensus is identical to political voting.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing normative philosophy of science (Popper) with descriptive sociology of science (Kuhn).', 'Distinguish between how science "ought" to work (Popper) vs how humans "actually" act (Kuhn).', 1.7, 1.2, 0.25, true, 0, 'Cambridge IGCSE / O-Level High Distinction'),
('ENG-910-SYN-10', 'English Literacy', 'synthesis', '9-10', 'olympiad', 'Economic Ledger: "High-income nations have reduced domestic greenhouse gas emissions by 20% since 2000." Consumption Analysis: "When calculated by final consumer demand (importing manufactured goods whose emissions are booked in developing exporter nations), high-income national carbon footprints have actually increased by 8%." What synthesis deconstructs the domestic emissions claim?', '[{"text":"High-income nations have completely eliminated fossil fuel usage across all sectors.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Developing nations emit carbon purely for amusement rather than export production.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Apparent domestic decarbonization in wealthy nations is largely an accounting illusion driven by the offshoring of emissions-intensive manufacturing to developing economies.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Imported manufactured goods do not generate carbon emissions during international maritime shipping.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing territorial carbon accounting with consumption-based trade flows.', 'If a country stops making steel at home and imports it from abroad, did emissions really drop?', 1.7, 1.1, 0.25, true, 0, 'ICSE Class 10 National Merit Tier'),
('ENG-910-EVL-01', 'English Literacy', 'evaluatingReflecting', '9-10', 'standard', '"The columnist opens his editorial with a lyrical, nostalgic portrait of idyllic self-sufficient village life before arguing against subsidized rural broadband internet." What rhetorical purpose does this opening portrait serve?', '[{"text":"It refutes claims that agricultural yields correlate with telecommunications access.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It provides audited economic figures on agricultural infrastructure spending.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It constructs a romanticized pastoral ideal to frame modern digital connectivity as disruptive and culturally corrupting.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"It demonstrates personal technical expertise in fiber-optic cable installation.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating nostalgic pastoral framing as a rhetorical strategy against technological modernization.', 'Why begin an argument against broadband with a romantic picture of village life without technology?', 1.35, 0.3, 0.25, true, 0, 'Cambridge IGCSE English Language'),
('ENG-910-EVL-02', 'English Literacy', 'evaluatingReflecting', '9-10', 'standard', '"The corporate spokesperson defended the chemical spill by stating: ''All environmental parameters are currently trending toward optimal equilibrium.'' How does the author characterize this response?', '[{"text":"As an apology accompanied by immediate financial compensation to victims.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"As an accurate, transparent, and courageous scientific acknowledgment of liability.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"As bureaucratic, obfuscating jargon designed to downplay catastrophic contamination and evade accountability.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"As a legal lawsuit filed against municipal wastewater operators.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing corporate obfuscation and sanitized technocratic language.', 'Notice how "trending toward optimal equilibrium" hides the fact that chemicals spilled.', 1.4, 0.4, 0.25, true, 0, 'Singapore Secondary 4 Express English'),
('ENG-910-EVL-03', 'English Literacy', 'evaluatingReflecting', '9-10', 'standard', 'In an editorial arguing against space exploration, the writer asks: "How dare we gaze at the stars through billion-dollar lenses when children in our own city go to bed hungry?" What rhetorical appeal is predominantly employed?', '[{"text":"Logos: an econometric cost-benefit calculation of aerospace manufacturing returns.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Pathos: an emotional appeal grounded in moral outrage and guilt to challenge resource allocation.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"Ethos: establishing the author''s academic credentials in astrophysics.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Kairos: analyzing the specific launch window of planetary orbital alignments.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Identifying rhetorical appeals (pathos, logos, ethos) and emotional argumentation.', 'Notice the emotional charge in "How dare we gaze at the stars while children go hungry".', 1.35, 0.3, 0.25, true, 0, 'US Common Core Grade 10 Argumentation'),
('ENG-910-EVL-04', 'English Literacy', 'evaluatingReflecting', '9-10', 'standard', 'A historian analyzes a 19th-century colonial diary: "The diarist documents indigenous harvesting methods not to understand local ecology, but to estimate taxable surplus for the imperial treasury." What does this observation reveal about the diarist''s perspective?', '[{"text":"The diary was forged by 20th-century counterfeiters to defame the colonial government.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The diarist was an objective botanical scientist committed to biodiversity conservation.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The diarist intended to surrender colonial authority to indigenous tribal councils.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The diarist''s gaze was purely extractive and administrative, viewing indigenous practices through the lens of colonial fiscal exploitation.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Evaluating colonial administrative perspectives and extractive bias in historical primary sources.', 'What is the difference between learning ecology vs calculating taxable surplus?', 1.4, 0.5, 0.25, true, 0, 'ICSE Class 10 History & English'),
('ENG-910-EVL-05', 'English Literacy', 'evaluatingReflecting', '9-10', 'advanced', '"The defense attorney conceded that her client''s conduct was ''unorthodox and unconventional,'' while vehemently rejecting the prosecution''s characterization of it as ''fraudulent and criminal.'' What semantic battle is being waged here?', '[{"text":"A grammatical debate regarding the etymological origin of Latin legal terms.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A struggle over legal framing: rebranding deliberate unlawful deception as benign eccentricity to avoid criminal conviction.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"An admission of guilt that automatically triggers an immediate maximum prison sentence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A personal insult aimed at the presiding appellate judge''s competence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing semantic reframing and euphemistic characterization in legal discourse.', 'Compare "unorthodox and unconventional" with "fraudulent and criminal".', 1.5, 0.7, 0.25, true, 0, 'Cambridge IGCSE First Language English'),
('ENG-910-EVL-06', 'English Literacy', 'evaluatingReflecting', '9-10', 'advanced', 'In reviewing a celebrated war memoir, a critic remarks: "The author displays extraordinary descriptive brilliance, but his total omission of civilian suffering renders the book an aesthetic celebration of tactical violence." What is the central moral critique?', '[{"text":"By selectively aestheticizing combat while erasing innocent casualties, the author sanitizes war into thrilling spectacle.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The author should have used simpler vocabulary to appeal to younger audiences.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The military memoir failed to include detailed maps of infantry fortifications.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The book contains factual inaccuracies regarding weapon caliber specifications.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Critiquing aestheticized violence and the ethical consequences of selective omission in war literature.', 'Notice the flaw: "total omission of civilian suffering renders the book an aesthetic celebration".', 1.55, 0.8, 0.25, true, 0, 'Singapore Secondary 4 Literature in English'),
('ENG-910-EVL-07', 'English Literacy', 'evaluatingReflecting', '9-10', 'advanced', '"The tech executive proclaimed that privacy is an obsolete concept in the modern era, conveniently ignoring that his own residential compound is shielded by armed guards and six-meter security walls." What rhetorical contradiction is exposed here?', '[{"text":"A legal dispute over property line easements with neighboring homeowners.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Hypocritical duality: demanding public transparency and data surrender from users while vigorously safeguarding his own elite personal sanctuary.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"An endorsement of open-source software licensing agreements.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A technical design failure in residential perimeter fence construction.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Exposing hypocrisy and ideological inconsistency through behavioral juxtaposition.', 'He tells the public privacy is dead, but surrounds his own house with 6-meter walls.', 1.5, 0.7, 0.25, true, 0, 'US Common Core Grade 10 Critical Reading'),
('ENG-910-EVL-08', 'English Literacy', 'evaluatingReflecting', '9-10', 'olympiad', '"When the author shifts from authoritative third-person omniscient narration to fractured, disjointed interior monologue during the catastrophe scene, what epistemological shift occurs for the reader?"', '[{"text":"The narrative register formally adopts the legal language of accident inquest transcripts.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The author indicates that the entire plot was a fabricated dream sequence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The reader is stripped of panoramic objective certainty and plunged into subjective trauma, disorientation, and panic.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The pacing decelerates to insert detailed biographical flashbacks of secondary characters.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing the psychological and epistemic impact of sudden point-of-view disruptions.', 'What happens to the reader when objective storytelling suddenly turns into fractured inner panic?', 1.65, 1, 0.25, true, 0, 'Singapore English Olympiad Senior'),
('ENG-910-EVL-09', 'English Literacy', 'evaluatingReflecting', '9-10', 'olympiad', '"The satirist praises the media corporation for ''magnanimously simplifying political discourse into twenty-second gladiatorial soundbites, thereby sparing the public the exhausting ordeal of nuanced thought.'' What satirical target is being assaulted?"', '[{"text":"The high licensing fees charged for live broadcast television frequencies.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The degradation of democratic civic deliberation into sensationalized, anti-intellectual entertainment for commercial profit.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The decline of classical Roman gladiatorial arena fighting techniques.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The inability of political candidates to purchase digital advertising billboard slots.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing sustained irony and satirical attacks on media commodification.', 'Notice the bitter irony: calling sensationalized soundbites "magnanimous".', 1.7, 1.1, 0.25, true, 0, 'Cambridge IGCSE Literature / First Language English'),
('ENG-910-EVL-10', 'English Literacy', 'evaluatingReflecting', '9-10', 'olympiad', '"The historian asserts: ''To label the 19th-century treaty a ''voluntary commercial partnership'' is an insult to language itself; the ink was scarcely dry before naval gunboats were positioned in the harbor to enforce compliance.''" What argument does this caustic metaphor solidify?', '[{"text":"The treaty negotiations were conducted under international maritime admiralty law.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The naval gunboats were sent to protect merchant ships from local pirates.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The treaty was an act of coercive imperial subjugation under threat of violent bombardment, completely void of genuine mutual consent.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The treaty expired naturally because paper and ink decayed in tropical humidity.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating historical demystification, moral clarity, and the exposure of gunboat diplomacy.', 'How can a treaty be "voluntary" if gunboats are aimed at the harbor to enforce it?', 1.75, 1.2, 0.25, true, 0, 'ICSE Class 10 English Literature Olympiad')
ON CONFLICT (scenario_code) DO UPDATE SET
  subject = EXCLUDED.subject,
