  international_benchmark = EXCLUDED.international_benchmark;

INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-1112-UND-01', 'English Literacy', 'understanding', '11-12', 'standard', '"Post-structuralist historiography posits that archival documents do not merely reflect past reality; rather, they encode the institutional power structures that authorized and curated their preservation." What does this premise imply for historical inquiry?', '[{"text":"State institutions actively destroyed all private correspondence to prioritize public proclamations.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Archival preservation is an entirely objective, value-neutral technical curation process.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Historical texts written before the printing press contain zero verifiable chronological data.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Researchers must critically interrogate what omissions, silences, and biases were structurally produced by the institutions safeguarding the records.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Deconstructing post-structuralist historiographical epistemology and archival power dynamics.', 'If archives encode power structures, what must historians ask about what was left out or preserved?', 1.4, 0.9, 0.25, true, 0, 'IB Diploma Language A Literature / Cambridge A-Level'),
('ENG-1112-UND-02', 'English Literacy', 'understanding', '11-12', 'standard', '"The philosopher argued that contemporary existential dread is not born from a scarcity of choices, but from the paralyzing vertigo of infinite, ungrounded possibilities in a secularized world lacking binding moral teleology." What is identified as the root of modern existential anxiety?', '[{"text":"The dizzying burden of absolute subjective freedom in the absence of preordained purpose or objective moral anchors.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The total absence of personal freedom under authoritarian political regimes.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A genetic neurochemical deficiency in serotonin receptors across Western populations.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Economic poverty resulting from pre-industrial agricultural subsistence.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting existential philosophy, teleological absence, and the vertigo of radical freedom.', 'Notice: "paralyzing vertigo of infinite possibilities" in a world "lacking binding moral teleology".', 1.45, 1, 0.25, true, 0, 'AP English Literature & Composition'),
('ENG-1112-UND-03', 'English Literacy', 'understanding', '11-12', 'standard', '"In semiotic analysis, the linguistic sign is fundamentally arbitrary; the signifier (the acoustic sound-image ''tree'') maintains no intrinsic, natural connection to the signified (the botanical organism)." What is the core assertion of Saussurean semiotics presented here?', '[{"text":"Written dictionaries must be rewritten annually to reflect botanical classification updates.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Spoken words possess mystical acoustic frequencies that physically alter plant growth.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Language is a conventional, culturally mediated system of relational differences rather than a mimetic reflection of physical reality.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Onomatopoeic words constitute the entire foundational lexicon of all human languages.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Understanding foundational structural linguistics and the arbitrariness of the sign.', 'The connection between the word sound and the actual object is arbitrary and culturally agreed upon.', 1.45, 1.1, 0.25, true, 0, 'Singapore-Cambridge GCE A-Level H2 Literature'),
('ENG-1112-UND-04', 'English Literacy', 'understanding', '11-12', 'standard', '"The architectural critic notes that the glass skyscraper''s relentless specular transparency is profoundly deceptive: while professing democratic openness, its reflective skin repels scrutiny and hermetically seals the financial elite from the street below." What paradox is diagnosed here?', '[{"text":"The structural instability of steel trusses in earthquake zones.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Glass windows that allow excessive solar thermal gain into office cubicles.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Ostensible visual accessibility that actually functions as an exclusionary, fortified barrier against civic engagement.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A municipal regulation requiring all commercial buildings to install mirrored windows.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing ideological paradoxes in contemporary architectural theory.', 'Contrast the appearance of "democratic openness" with "hermetically sealing the elite".', 1.5, 1, 0.25, true, 0, 'CBSE Class 12 English Core'),
('ENG-1112-UND-05', 'English Literacy', 'understanding', '11-12', 'standard', '"The psychoanalytic theorist observes that the uncanny (das Unheimliche) arises not from encountering the utterly alien, but from the sudden, terrifying resurgence of something intimately familiar that had been repressed." What defines the psychological trigger of the uncanny?', '[{"text":"A cognitive failure to remember childhood telephone numbers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The phobia of extraterrestrial spacecraft or foreign languages.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"A rational physiological reaction to sudden optical darkness.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The disquieting return of an estranged, repressed inner trauma masquerading as an external monstrosity.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Analyzing Freudian psychoanalytic theory regarding the uncanny in literature.', 'Notice: not the "utterly alien", but the resurgence of something "intimately familiar that had been repressed".', 1.5, 1.1, 0.25, true, 0, 'Cambridge International A-Level English Literature'),
('ENG-1112-UND-06', 'English Literacy', 'understanding', '11-12', 'advanced', '"Ecocritical theory deconstructs the binary between ''nature'' and ''civilization,'' arguing that the myth of a pristine, external wilderness abdicates human ecological accountability by imagining nature as a separate, self-healing sanctuary." What critique does this perspective level against traditional Romantic environmentalism?', '[{"text":"Wildlife conservation is biologically impossible without commercial logging concessions.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Romantic poetry provides audited quantitative metrics for atmospheric carbon sequestration.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Industrial urban centers should be completely razed to restore untouched primeval wilderness.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Idealizing nature as a detached, pure Eden obscures humanity''s pervasive, inescapable entwinement within anthropogenically altered planetary networks.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Evaluating ecocritical deconstruction of the pristine wilderness myth.', 'Think about how imagining nature as "separate and pure" lets humans off the hook for their daily impact.', 1.55, 1.3, 0.25, true, 0, 'IB Diploma Literature Higher Level'),
('ENG-1112-UND-07', 'English Literacy', 'understanding', '11-12', 'advanced', '"The legal theorist contends that the doctrine of original intent in constitutional jurisprudence operates as an epistemic fiction, projecting modern ideological grievances backward onto dead framers who themselves disagreed on foundational principles." What fundamental flaw does this critique attribute to originalism?', '[{"text":"Constitutional conventions were conducted exclusively in classical Greek.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The framers of the constitution were illiterate and left no written records.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It anachronistically invents a non-existent historical consensus to legitimize contemporary judicial preferences with artificial historical sanctity.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Original intent doctrine is mandated by the United Nations Charter.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing constitutional jurisprudence, originalism, and historiographical fiction.', 'Why call original intent an "epistemic fiction"? Because the framers themselves disagreed!', 1.6, 1.4, 0.25, true, 0, 'Singapore GCE A-Level General Paper'),
('ENG-1112-UND-08', 'English Literacy', 'understanding', '11-12', 'advanced', '"In modernist stream-of-consciousness narratives, the collapse of chronological syntactical order reflects an epistemological crisis: the conviction that external clock time is a sterile abstraction unable to capture the chaotic, polyphonic reality of subjective human consciousness." What thematic revelation drives this narrative technique?', '[{"text":"Linear chronology is an artificial construct; authentic human experience is an entangled, non-linear continuum of memory, perception, and sensation.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Modernist authors lacked knowledge of standard mechanical clock mechanisms.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Stream-of-consciousness was invented to reduce printing press typesetting costs.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Objective clock time accurately mirrors the neurological structure of the human brain.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing modernist epistemological crisis and temporal fluidity in stream-of-consciousness.', 'Notice the contrast between "sterile external clock time" and "polyphonic subjective consciousness".', 1.6, 1.3, 0.25, true, 0, 'AP English Literature / Cambridge A-Level'),
('ENG-1112-UND-09', 'English Literacy', 'understanding', '11-12', 'olympiad', '"The critical theorist argues that algorithmic surveillance capitalism does not merely predict consumer behavior—it manufactures behavioral futures, modifying human volition through real-time feedback loops to guarantee profitability for proprietary prediction markets." What profound transformation of human agency is articulated?', '[{"text":"The total elimination of financial credit card fraud across e-commerce platforms.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The voluntary participation of citizens in municipal democratic assemblies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"An improvement in digital keyboard typing accuracy through machine learning.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The degradation of free human self-determination into engineered behavioral compliance optimized for commercial extraction.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Deconstructing Zuboffian surveillance capitalism and the expropriation of human behavioral agency.', 'Notice: not merely predicting behavior, but "manufacturing behavioral futures" and "modifying volition".', 1.7, 1.6, 0.25, true, 0, 'International English Olympiad / World Universities Debating Championship'),
('ENG-1112-UND-10', 'English Literacy', 'understanding', '11-12', 'olympiad', '"Adorno and Horkheimer''s critique of the ''culture industry'' posits that mass-produced commodified entertainment does not offer authentic liberation from the exhausting monotony of industrial labor; rather, it reproduces labor''s mechanized discipline, conditioning consumers to passively accept the status quo in their leisure time." What paradoxical function of modern mass entertainment is unmasked?', '[{"text":"Commodified cinema requires excessive intellectual effort that exhausts consumer audiences.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Mass entertainment inspires working-class populations to launch immediate political insurrections.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Far from providing genuine psychological freedom, commercial leisure actively inoculates workers with passive conformity and reinforces systemic alienation.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Pre-industrial folk music was mass-manufactured in commercial recording studios.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deconstructing Frankfurt School critical theory regarding the culture industry and passive ideological reproduction.', 'How does mass entertainment keep people obedient even while they think they are relaxing?', 1.75, 1.7, 0.25, true, 0, 'Cambridge A-Level Distinction / Oxbridge Entrance Examination'),
('ENG-1112-LOC-01', 'English Literacy', 'locatingInformation', '11-12', 'standard', 'Constitutional Precedent Summary: "In Matter of Jurisdiction [2024] UKSC 12, the Supreme Court held that extraterritorial discovery orders are justiciable under Article 6(1) only when the subject entity maintains a substantial corporate nexus within the forum state, explicitly distinguishing the jurisdictional test established in Al-Skeini." According to this ruling, when do extraterritorial discovery orders become justiciable under Article 6(1)?', '[{"text":"Only in criminal prosecutions involving maritime salvage treaties.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Whenever diplomatic immunity is formally waived by the executive branch.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Under identical jurisdictional criteria as those formulated in Al-Skeini.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Strictly when the subject entity possesses a substantial corporate nexus within the forum state.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating precise jurisdictional thresholds in high-level appellate judicial precedent.', 'Find the condition right after "only when".', 1.45, 0.9, 0.25, true, 0, 'Cambridge International A-Level Law & English'),
('ENG-1112-LOC-02', 'English Literacy', 'locatingInformation', '11-12', 'standard', 'Bioengineering Research Protocol: "To achieve CRISPR-Cas12a target trans-cleavage: guide RNA must contain a 20-nucleotide target-complementary spacer flanked by a 5''-TTTV protospacer adjacent motif (PAM), with ribonucleoprotein incubation conducted in 10 mM Tris-HCl (pH 7.9) at 37°C for 45 minutes." What exact protospacer adjacent motif (PAM) sequence is specified?', '[{"text":"5''-TTTV","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"3''-NGG","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"20-nucleotide Tris-HCl","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"pH 7.9","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning high-density molecular bioengineering literature for specific genomic sequences.', 'Scan for the acronym "PAM".', 1.4, 0.8, 0.25, true, 0, 'Singapore GCE A-Level H2 Biology & English'),
('ENG-1112-LOC-03', 'English Literacy', 'locatingInformation', '11-12', 'standard', 'International Trade Arbitration Award: "Under Article 37.4 of the UNCITRAL Rules, compound interest shall accrue at the 6-month SOFR rate plus a margin of 2.75%, capitalized semi-annually from the date of breach (October 14, 2021) until satisfaction of the award." What interest margin is added to the 6-month SOFR base rate?', '[{"text":"37.4%","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"6% compounded annually","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"A margin of 2.75%","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Zero margin","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting precise financial penalty formulas from international commercial arbitration awards.', 'Look for the phrase "plus a margin of".', 1.45, 0.9, 0.25, true, 0, 'IB Diploma English A Language and Literature'),
('ENG-1112-LOC-04', 'English Literacy', 'locatingInformation', '11-12', 'standard', 'Treaty on Outer Space Demilitarization: "Article IV Clause 2: The establishment of military bases, installations, and fortifications, the testing of any type of weapons, and the conduct of military maneuvers on celestial bodies shall be forbidden, though the use of military personnel for scientific research or other peaceful purposes is not prohibited." Under what circumstance is military personnel permitted on celestial bodies?', '[{"text":"For constructing planetary fortifications during geopolitical crises.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"For scientific research or other peaceful purposes.","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"For testing defensive kinetic projectile weapons.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Under no circumstances whatsoever; all military personnel are barred.","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating express legal exceptions within restrictive international disarmament covenants.', 'Find the clause starting with "though the use of military personnel for...".', 1.5, 1, 0.25, true, 0, 'AP English Language / Cambridge A-Level General Paper'),
('ENG-1112-LOC-05', 'English Literacy', 'locatingInformation', '11-12', 'standard', 'Climatological Paleocores Report: "Analysis of the EPICA Dome C Antarctic ice core reveals that during the Mid-Brunhes Event (430,000 BP), atmospheric CO₂ varied between 180 ppm in glacial maxima and 298 ppm during Marine Isotope Stage 11 (MIS 11), with delta-¹⁸O isotopic shifts indicating Antarctic polar temperatures 2.4°C above pre-industrial baselines." What peak CO₂ concentration was recorded during MIS 11?', '[{"text":"180 ppm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"298 ppm","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"430,000 ppm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2.4 ppm","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning multidimensional paleoclimatic datasets for specific stage-linked atmospheric metrics.', 'Connect "Marine Isotope Stage 11" directly with its CO₂ ppm figure.', 1.5, 1, 0.25, true, 0, 'Singapore GCE A-Level H2 Geography & Literature'),
('ENG-1112-LOC-06', 'English Literacy', 'locatingInformation', '11-12', 'advanced', 'Financial Derivatives Regulatory Standard (Basel IV): "Section 18.1: Counterparty Credit Risk (SA-CCR) dictates that the Alpha multiplier for calculating Exposure at Default (EAD) is fixed at 1.4, except for cleared transactions with Qualifying Central Counterparties (QCCPs) where an exemption factor applies only if default fund contributions are bankruptcy-remote." What is the fixed Alpha multiplier for calculating EAD under standard transactions?', '[{"text":"Zero multiplier","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"18.1","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Fixed at 1.4","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"2.5","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting fixed calculation coefficients from multi-clause prudential banking regulations.', 'Scan for "Alpha multiplier for calculating Exposure at Default (EAD) is fixed at".', 1.55, 1.2, 0.25, true, 0, 'Cambridge International A-Level Business & Economics'),
('ENG-1112-LOC-07', 'English Literacy', 'locatingInformation', '11-12', 'advanced', 'Astrophysical Gravitational Wave Observatory Log: "Event GW230814 registered a signal-to-noise ratio of 26.4 in the Livingston interferometer and 19.8 in Hanford, localized to a 90% credible sky area of 38 deg². Luminosity distance was inferred at 780 Mpc (z ≈ 0.16) with estimated primary progenitor mass of 31.4 solar masses." What was the inferred luminosity distance to event GW230814?', '[{"text":"38 deg²","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"780 Mpc (z ≈ 0.16)","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"26.4 Mpc","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"31.4 Mpc","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting precise cosmological distances from gravitational wave detection catalogues.', 'Look for "Luminosity distance was inferred at".', 1.55, 1.1, 0.25, true, 0, 'Singapore GCE A-Level H2 Physics & General Paper'),
('ENG-1112-LOC-08', 'English Literacy', 'locatingInformation', '11-12', 'advanced', 'Pharmacogenomics Clinical Guidance: "For patients carrying the CYP2C19*2 or *3 loss-of-function alleles (poor metabolizers), standard clopidogrel antiplatelet therapy exhibits a 48% reduction in active thiol metabolite generation; clinical guidelines mandate transitioning to prasugrel (10 mg daily) or ticagrelor (90 mg twice daily), provided history of intracranial hemorrhage is absent." What dosage of ticagrelor is recommended as an alternative?', '[{"text":"48 mg once daily","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"10 mg daily","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"90 mg twice daily","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"2 mg twice daily","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exact pharmaceutical alternative dosages across complex pharmacogenomic clinical guidelines.', 'Pair "ticagrelor" with its exact dose and dosing frequency.', 1.6, 1.3, 0.25, true, 0, 'US AP Biology / Advanced Reading Technical'),
('ENG-1112-LOC-09', 'English Literacy', 'locatingInformation', '11-12', 'olympiad', 'Maritime Boundary Adjudication: "The International Court of Justice determined that the provisional equidistance line must be adjusted seaward by 14.2 nautical miles along Azimuth 246° to account for the disproportionate coastal concavity of Bay Alpha, thereby ensuring that the ratio of coastal lengths (1:1.68) mirrors the allocated maritime space." What azimuth heading was designated for the 14.2-nautical-mile adjustment?', '[{"text":"Azimuth 168°","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Azimuth 246°","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Azimuth 14.2°","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Azimuth 90°","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Isolating exact nautical bearings within multilateral international border dispute awards.', 'Find the degree heading following "along Azimuth".', 1.7, 1.5, 0.25, true, 0, 'Singapore English Olympiad Senior Finals'),
('ENG-1112-LOC-10', 'English Literacy', 'locatingInformation', '11-12', 'olympiad', 'Quantum Cryptographic Architecture: "In the BB84 protocol implementation with decoy states, pulse intensity for signal states was calibrated at mu = 0.48 photons/pulse, decoy state nu1 at 0.12 photons/pulse, and vacuum state nu2 at 0.002 photons/pulse, achieving a secure key rate of 2.4 kbps over 140 km of low-loss optical fiber." What was the calibrated photon intensity for decoy state nu1?', '[{"text":"0.002 photons/pulse","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.48 photons/pulse","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.12 photons/pulse","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"2.4 photons/pulse","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning complex quantum protocol parameter tables for specific sub-state calibration values.', 'Look specifically for decoy state "nu1".', 1.75, 1.6, 0.25, true, 0, 'Cambridge A-Level Distinction / IPhO English Integration')
